-- el_lessons 44ef53cc-5c4e-4572-af64-8e2206b71f82: Lá thư Will để lại cho Clark ở Paris
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"7ee7ebc2-01b8-468b-8d2a-cca78882a25a","title":"Me Before You - Louisa and Will - Photograph and Letter","status":"published","transcript":[{"end":19440,"text":"Loving can hurt","start":15600},{"end":24200,"text":"Loving can hurt sometimes","start":19440},{"end":31370,"text":"But it's the only thing that I know","start":23250},{"end":37930,"text":"When it gets hard","start":31370},{"end":42670,"text":"You know it can get hard sometimes","start":37930},{"end":51370,"text":"It is the only thing that makes us feel alive","start":42670},{"end":56920,"text":"We keep this love in a photograph","start":51370},{"end":61640,"text":"We made these memories for ourselves","start":56920},{"end":64050,"text":"Where our eyes are never closing","start":61640},{"end":66300,"text":"Hearts are never broken","start":64050},{"end":69680,"text":"Times forever frozen still","start":66300},{"end":72900,"text":"So you can keep me","start":69680},{"end":75300,"text":"Inside the pocket","start":72900},{"end":77480,"text":"Of your ripped jeans","start":75300},{"end":79580,"text":"Holdin' me closer","start":77480},{"end":82030,"text":"'Til our eyes meet","start":79580},{"end":86890,"text":"You won't ever be alone","start":82030},{"end":92770,"text":"Wait for me to come home","start":86890},{"end":95070,"text":"Loving can heal","start":92260},{"end":99990,"text":"Loving can mend your soul","start":95070},{"end":106770,"text":"And it's the only thing that I know (know)","start":97470},{"end":112940,"text":"I swear it will get easier","start":106770},{"end":117640,"text":"Remember that with every piece of ya","start":112940},{"end":126280,"text":"And it's the only thing we take with us when we die","start":117640},{"end":132080,"text":"We keep this love in this photograph","start":126280},{"end":136960,"text":"We made these memories for ourselves","start":132080},{"end":139310,"text":"Where our eyes are never closing","start":136960},{"end":141720,"text":"Our hearts were never broken","start":139310},{"end":145300,"text":"Times forever frozen still","start":141720},{"end":148540,"text":"So you can keep me","start":145300},{"end":150720,"text":"Inside the pocket","start":148540},{"end":153010,"text":"Of your ripped jeans","start":150720},{"end":155180,"text":"Holdin' me closer","start":153010},{"end":157300,"text":"'Til our eyes meet","start":155180},{"end":162510,"text":"You won't ever be alone","start":157300},{"end":166220,"text":"And if you hurt me","start":162510},{"end":170770,"text":"That's OK, baby, only words bleed","start":166220},{"end":175140,"text":"Inside these pages you just hold me","start":170770},{"end":179660,"text":"And I won't ever let you go","start":175140},{"end":198680,"text":"Wait for me to come home","start":179660},{"end":201870,"text":"Oh you can fit me","start":198680},{"end":206260,"text":"Inside the necklace you got when you were 16","start":201870},{"end":208410,"text":"Next to your heartbeat","start":206260},{"end":210610,"text":"Where I should be","start":208410},{"end":216750,"text":"Keep it deep within your soul","start":210610},{"end":219560,"text":"And if you hurt me","start":217490},{"end":224060,"text":"Well, that's OK, baby, only words bleed","start":219560},{"end":228370,"text":"Inside these pages you just hold me","start":224060},{"end":233800,"text":"And I won't ever let you go","start":228370},{"end":237340,"text":"When I'm away","start":233800},{"end":241770,"text":"I will remember how you kissed me","start":237340},{"end":244180,"text":"Under the lamppost","start":241770},{"end":246450,"text":"Back on 6th street","start":244180},{"end":250100,"text":"Hearing you whisper through the phone,","start":246450},{"end":254500,"text":"\"Wait for me to come home.\"","start":250100},{"end":259169,"text":"Clark, a few weeks should have passed by the time you read this.","start":254560},{"end":262430,"text":"If you followed the instructions, you'll be in Paris","start":259600},{"end":266129,"text":"on one of those chairs that never sit quite level on the pavement.","start":262720},{"end":267710,"text":"I hope it's still sunny.","start":266160},{"end":273889,"text":"Across the bridge to your right, you will see L'Artisan Parfumeur.","start":270240},{"end":276870,"text":"You should try the scent called Papillons Extrême.","start":274240},{"end":279190,"text":"I always did think it would smell great on you.","start":277040},{"end":287919,"text":"There are a few things I wanted to say and couldn't,","start":284639},{"end":291050,"text":"because you would have got all emotional and you wouldn't have let me finish.","start":287919},{"end":296410,"text":"So, here it is.","start":294080},{"end":303629,"text":"When you get back home, Michael Lawler will give you access to a bank account that contains enough to give you a new beginning.","start":297360},{"end":305520,"text":"Don't start panicking.","start":303759},{"end":310390,"text":"It's not enough for you to sit around for the rest of your life, but it should buy you your freedom.","start":305520},{"end":314590,"text":"Wear those stripy legs with pride.","start":312400},{"end":317690,"text":"Knowing you still have possibilities is a luxury.","start":314960},{"end":322890,"text":"Knowing I might have given them to you has eased something for me.","start":318479},{"end":326730,"text":"So, this is it.","start":324000},{"end":330720,"text":"You are scored on my heart, Clark.","start":327600},{"end":332720,"text":"You were from the first day you walked in","start":330720},{"end":336880,"text":"with your sweet smile and your ridiculous clothes and your bad jokes","start":332720},{"end":340609,"text":"and your complete inability to ever hide a single thing you felt.","start":336880},{"end":344430,"text":"Don't think of me too often.","start":342720},{"end":346710,"text":"I don't want you getting sad.","start":345120},{"end":348609,"text":"Just live well.","start":347360},{"end":351329,"text":"Just live.","start":350240},{"end":355510,"text":"I'll be walking beside you every step of the way.","start":353039},{"end":358770,"text":"Love, Will.","start":357440}],"channel_name":"Christopher Shaw","date_created":"2026-11-23T07:29:59.792+00:00","date_updated":null,"yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi_webp/xY207AovuMY/sddefault.webp","transcript_kind":"manual","transcript_lang":"en","youtube_video_id":"xY207AovuMY","transcript_updated_at":"2026-11-23T07:35:27.030508+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = 'xY207AovuMY') on conflict do nothing;
