-- el_lessons 7c97feca-802f-45ef-b51b-5691d41017a3: Hết tiền? Hát cho ATM một bài là có!
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"bbcec819-5dc8-5fa1-b901-2852bb0f7ce2","title":"Sam & Cat | Magic ATM | Nickelodeon UK","status":"published","transcript":[{"end":3000,"text":"Hey, we should go buy more cool stuff.","start":500},{"end":6000,"text":"Uh-uh. I can't afford to buy new stuff.","start":3000},{"end":8400,"text":"Well, I'll pay for it.","start":6000},{"end":10000,"text":"With what?","start":8400},{"end":11400,"text":"With this.","start":10000},{"end":14800,"text":"What? Where did you get that fat wad?","start":11400},{"end":17700,"text":"From an ATM.","start":14800},{"end":20000,"text":"How many times does she gotta tell you?","start":17700},{"end":22200,"text":"So you wanna keep asking questions,","start":20000},{"end":24600,"text":"or you wanna go buy more cool stuff?","start":22200},{"end":29000,"text":"Look, I just wanna be sure that it's cool stuff.","start":24600},{"end":31700,"text":"But, uh, can we stop by your ATM first?","start":29000},{"end":33800,"text":"Sure, if you wanna. Oh!","start":31700},{"end":36400,"text":"Hey, what's up, guys?","start":33800},{"end":39600,"text":"Hey, can you, uh, watch these two kids for us?","start":36400},{"end":41500,"text":"Oh, I can't.","start":39600},{"end":48500,"text":"You guys wanna feel my hair tuft?","start":45900},{"end":52000,"text":"Yeah, you do.","start":48500},{"end":58900,"text":"Hey!","start":56600},{"end":63800,"text":"Yeah?","start":62500},{"end":66300,"text":"Which of these pictures make me look hot?","start":63800},{"end":68600,"text":"This? No. Gross.","start":66300},{"end":71400,"text":"This? Gross. No.","start":68600},{"end":74200,"text":"This? Ugh. This? Ew.","start":71400},{"end":77000,"text":"I'll take more selfies.","start":74200},{"end":80800,"text":"So this is your ATM?","start":78500},{"end":81900,"text":"Yarp.","start":80800},{"end":84200,"text":"But you don't have a bank account.","start":81900},{"end":84900,"text":"No.","start":84200},{"end":86800,"text":"Well, then how'd you get an ATM card?","start":84900},{"end":88600,"text":"I don't have an ATM card.","start":86800},{"end":92200,"text":"Well, then how are you getting money out of an ATM machine?","start":88600},{"end":93500,"text":"The tones.","start":92200},{"end":95400,"text":"The tones. Okay, we keep saying \"the tones\",","start":93500},{"end":97100,"text":"but I still have no idea what \"the tones\" means.","start":95400},{"end":99200,"text":"Push the button.","start":97100},{"end":105400,"text":"See, every time you press one of those","start":102100},{"end":108400,"text":"number buttons, you can hear a beep.","start":105400},{"end":111000,"text":"And this is big news there in your bunny brain?","start":108400},{"end":113400,"text":"Oh, yeah, 'cause, you know,","start":111000},{"end":115400,"text":"I started thinking of that old song, you know,","start":113400},{"end":121400,"text":"♪ (Cat sings her own version: basement, buckets, cheese) ♪","start":115400},{"end":123400,"text":"Wait, wait. No, no, no, no. What?","start":121400},{"end":125900,"text":"It's \"Take Me Out to the Ball Game.\"","start":123400},{"end":127300,"text":"Huh?","start":125900},{"end":133400,"text":"♪ (Sam sings the real opening) ♪","start":127300},{"end":135900,"text":"Those lyrics make no sense.","start":133400},{"end":139200,"text":"Anyway! Oh, I started wondering if I could play that","start":135900},{"end":142500,"text":"song with these number buttons. See?","start":139200},{"end":151800,"text":"♪ (Cat plays the tune on the keypad) ♪","start":143000},{"end":154500,"text":"See? 400 bucks.","start":152100},{"end":156500,"text":"Holy buckets of cheese!","start":154500},{"end":158300,"text":"What did she say?","start":156500},{"end":160800,"text":"Nothing. Take more selfies.","start":158300},{"end":162800,"text":"Yes! I love to selfie.","start":160800},{"end":165000,"text":"How many times have you done this?","start":162800},{"end":167400,"text":"I don't know, like two or three times...","start":165000},{"end":168800,"text":"a day.","start":167400},{"end":170400,"text":"What?","start":168800},{"end":173900,"text":"Listen,","start":170400},{"end":176600,"text":"you cannot tell anyone about this.","start":173900},{"end":177900,"text":"Why?","start":176600},{"end":179600,"text":"It's not stealing.","start":177900},{"end":183400,"text":"I just play a song and the machine thanks me with cash.","start":179600},{"end":188800,"text":"I know, but I... I'm not sure this is legal.","start":183400},{"end":191600,"text":"Oh. Should I give this back?","start":188800},{"end":194200,"text":"Well, I didn't say that.","start":191600},{"end":196000,"text":"Then what should we do?","start":194200},{"end":199400,"text":"I say we think about it","start":196000},{"end":204500,"text":"while we buy stuff at the mall.","start":199400}],"channel_name":"Nickelodeon UK","date_created":"2026-11-26T04:55:26.81703+00:00","date_updated":"2026-11-26T04:55:26.81703+00:00","yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi/-WL68Rm_ElY/hqdefault.jpg","transcript_kind":"asr","transcript_lang":"en","youtube_video_id":"-WL68Rm_ElY","transcript_updated_at":"2026-11-26T04:55:26.81703+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = '-WL68Rm_ElY') on conflict do nothing;
