  insert into el_lessons select (jsonb_populate_record(null::el_lessons, $row${"id":"7c97feca-802f-45ef-b51b-5691d41017a3","note":null,"sort":500,"intro":"Cô bạn này không đi làm thêm, cũng chẳng trúng số, vậy mà trong tay cả xấp tiền. Bí quyết nghe xong chỉ muốn ra cây ATM hát thử.","level":5,"title":"Hết tiền? Hát cho ATM một bài là có!","topic":"film_story","end_ms":204800,"status":"draft","explore":["Vì sao buồn cười? Sam hỏi theo logic đời thật (tài khoản đâu, thẻ đâu), còn Cat trả lời bằng logic riêng. Cat hát sai bét lời một bài ai ở Mỹ cũng biết, rồi lại chê lời ĐÚNG là vô nghĩa. Sau đó chính Sam kêu “Holy buckets of cheese!”, mượn luôn lời hát chế. Cuối cùng, người vừa lo phạm pháp lại là người rủ đi mua sắm trước.","“Take Me Out to the Ball Game” (1908) của Jack Norworth và Albert Von Tilzer thường được khán giả Mỹ hát chung giữa hiệp bảy của trận bóng chày. Ngoài đời, bấm nhạc trên phím ATM không làm máy nhả tiền: đó chỉ là chuyện phim."],"summary":"Cat rủ Sam đi mua sắm và rút ra một xấp tiền, bảo là lấy từ ATM. Tới cửa hàng, Sam mới biết Cat không có tài khoản ngân hàng, cũng không có thẻ. Cat nghe tiếng bíp của các phím số, nhớ tới một bài hát cũ (theo lời tự chế về phô mai), rồi bấm giai điệu đó trên bàn phím và máy nhả ra 400 đô. Sam lo chuyện này không hợp pháp, nhưng khi Cat hỏi có nên trả lại không, Sam đề nghị cứ vừa đi mua sắm vừa suy nghĩ.","short_id":"c8f21167","start_ms":200,"is_premium":false,"listen_for":"Biết bí mật cây ATM rồi, cuối cùng Sam đề nghị làm gì?","date_created":"2026-11-26T04:58:11.767975+00:00","date_updated":"2026-11-26T04:58:11.767975+00:00","source_video_id":"bbcec819-5dc8-5fa1-b901-2852bb0f7ce2"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
  insert into el_segments ("n", "id", "end_ms", "start_ms", "lesson_id") select "n", "id", "end_ms", "start_ms", "lesson_id" from jsonb_populate_recordset(null::el_segments, $row$[{"n":1,"id":"db0dd9cd-2df9-4e3d-8abc-0c5ce6d4d45d","end_ms":56000,"start_ms":200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":2,"id":"1c9702ee-a519-4fdc-b201-8a5db17fcacf","end_ms":151900,"start_ms":56000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":3,"id":"9539089b-6637-4d17-84a6-861abed996c5","end_ms":204800,"start_ms":151900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"}]$row$::jsonb) on conflict do nothing;
  insert into el_questions ("n", "id", "kind", "answer", "prompt", "explain", "options", "lesson_id", "answer_end", "segment_id", "answer_start") select "n", "id", "kind", "answer", "prompt", "explain", "options", "lesson_id", "answer_end", "segment_id", "answer_start" from jsonb_populate_recordset(null::el_questions, $row$[{"n":1,"id":"136bfecc-cb86-4939-81f1-22765d5931a7","kind":"detail","answer":0,"prompt":"Khi Sam cứ hỏi về xấp tiền, Cat phản ứng thế nào?","explain":"“So you wanna keep asking questions, or you wanna go buy more cool stuff?”","options":["Bắt Sam chọn: hỏi tiếp hay là đi mua đồ","Bảo Sam tự trả tiền cho đồ mới của mình","Nói đó là tiền công trông hai đứa trẻ"],"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3","answer_end":24600,"segment_id":"db0dd9cd-2df9-4e3d-8abc-0c5ce6d4d45d","answer_start":20000},{"n":2,"id":"8f66e7e0-f485-4dcf-8f25-c5d0e191ebe0","kind":"why","answer":1,"prompt":"Vì sao Sam không hiểu nổi chuyện Cat rút được tiền?","explain":"“But you don’t have a bank account… I don’t have an ATM card.”","options":["Vì Cat không nhớ nổi mật mã của tấm thẻ","Vì Cat không có tài khoản, cũng chẳng có thẻ","Vì cây ATM trong cửa hàng đã hỏng từ lâu"],"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3","answer_end":88600,"segment_id":"1c9702ee-a519-4fdc-b201-8a5db17fcacf","answer_start":81900},{"n":3,"id":"9223365b-2faf-4d14-b688-e4db04beba7b","kind":"attitude","answer":0,"prompt":"Khi được Sam nhắc lại lời đúng của bài hát, Cat nghĩ gì?","explain":"“Those lyrics make no sense.”","options":["Lời đúng đó nghe mới là chẳng có nghĩa gì","Lời của Sam hay hơn nên Cat xin học theo","Đó là một bài khác mà Cat chưa nghe bao giờ"],"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3","answer_end":135900,"segment_id":"1c9702ee-a519-4fdc-b201-8a5db17fcacf","answer_start":133400},{"n":4,"id":"4157d829-4259-4685-a1e4-daeede87b448","kind":"detail","answer":1,"prompt":"Cat làm chuyện này thường xuyên đến mức nào?","explain":"“Like two or three times… a day.”","options":["Mới đúng hai ba lần từ trước đến nay","Khoảng hai ba lần mỗi ngày","Chừng hai ba lần trong mỗi tuần"],"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3","answer_end":168800,"segment_id":"9539089b-6637-4d17-84a6-861abed996c5","answer_start":162800},{"n":5,"id":"9fc7d1ed-10b4-4108-bc72-4f863f6f2047","kind":"attitude","answer":1,"prompt":"Khi Cat hỏi có nên trả lại tiền không, Sam tỏ thái độ gì?","explain":"“Well, I didn’t say that.”","options":["Giận dữ vì Cat không chịu chia tiền","Ngập ngừng, không hẳn muốn trả lại","Dứt khoát bắt Cat đem trả ngay lập tức"],"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3","answer_end":194200,"segment_id":"9539089b-6637-4d17-84a6-861abed996c5","answer_start":188800},{"n":6,"id":"f60162ca-d5de-4564-b31a-1bd22a07bf45","kind":"gist","answer":0,"prompt":"Biết bí mật cây ATM rồi, cuối cùng Sam đề nghị làm gì?","explain":"“I say we think about it… while we buy stuff at the mall.”","options":["Vừa đi mua sắm vừa nghĩ xem nên làm sao","Kể cho người bán hàng nghe để xin lời khuyên","Trả tiền lại ngay rồi mới đi trung tâm mua sắm"],"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3","answer_end":201500,"segment_id":null,"answer_start":196000}]$row$::jsonb) on conflict do nothing;
  insert into el_vocab ("n", "id", "kind", "term", "forms", "at_end", "meaning", "at_start", "lesson_id") select "n", "id", "kind", "term", "forms", "at_end", "meaning", "at_start", "lesson_id" from jsonb_populate_recordset(null::el_vocab, $row$[{"n":1,"id":"f1cc02ce-bf60-41f4-ad85-f15b35386b07","kind":"word","term":"afford","forms":[],"at_end":3400,"meaning":"đủ tiền để mua, để trả","at_start":3200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":2,"id":"870cefae-0ec2-4301-8497-539a32eefeea","kind":"word","term":"wad","forms":[],"at_end":11800,"meaning":"xấp, cọc (tiền)","at_start":11600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":3,"id":"45d7779d-bc11-46a4-9bc8-c3bb355bdbf0","kind":"phrase","term":"bank account","forms":[],"at_end":82300,"meaning":"tài khoản ngân hàng","at_start":82100,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":4,"id":"188e5a73-cb2c-4c5e-ad9c-0158158ab2f5","kind":"word","term":"beep","forms":[],"at_end":105800,"meaning":"tiếng bíp","at_start":105600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":5,"id":"6bf28e1b-a471-4838-8a8d-d30b4c5eb9d8","kind":"word","term":"lyrics","forms":[],"at_end":133800,"meaning":"lời bài hát","at_start":133600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":6,"id":"e9c956e8-9d5a-44cc-9c43-3f8a22b5de22","kind":"word","term":"bucks","forms":["buck"],"at_end":152500,"meaning":"đô la (cách nói thân mật)","at_start":152300,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":7,"id":"7e1957b2-5d55-4e91-b15d-839faaaf9f23","kind":"word","term":"stealing","forms":["steal"],"at_end":178300,"meaning":"ăn cắp","at_start":178100,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":8,"id":"70ae8881-63d5-4322-bb44-2469e1f2a0da","kind":"word","term":"legal","forms":[],"at_end":183800,"meaning":"hợp pháp","at_start":183600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"}]$row$::jsonb) on conflict do nothing;
  insert into el_notes ("n", "id", "kind", "term", "extra", "forms", "before", "explain", "lesson_id") select "n", "id", "kind", "term", "extra", "forms", "before", "explain", "lesson_id" from jsonb_populate_recordset(null::el_notes, $row$[{"n":1,"id":"6b1dcbdb-3e5b-43db-bb54-47cafb08abef","kind":"culture","term":"hair tuft","extra":null,"forms":[],"before":false,"explain":"Chỏm tóc dựng hoặc bồng lên. Cậu bạn tóc xù dùng nó để dụ hai đứa trẻ.","lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":2,"id":"fea3f7bb-7368-4cc1-8956-6ef4405ea4fe","kind":"idiom","term":"Yarp","extra":"Tương tự “yup”, “yep”.","forms":[],"before":false,"explain":"Cách nói đùa của “yes”.","lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":3,"id":"3e7c1c7e-5d08-4e8f-a830-8df3926b5a96","kind":"culture","term":"the tones","extra":"Điện thoại bàn phím phát mỗi phím một âm khác nhau.","forms":["tones"],"before":false,"explain":"Ở đây là âm thanh phát ra khi bấm phím số.","lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":4,"id":"4c94fc3f-de3b-4fcd-be6a-84488cd3ec75","kind":"culture","term":"Take Me Out to the Ball Game","extra":null,"forms":[],"before":false,"explain":"Bài hát cổ động bóng chày rất quen ở Mỹ, ra đời năm 1908.","lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"n":5,"id":"2cb0304d-fd1a-41d2-b63f-9984763014a7","kind":"idiom","term":"Holy buckets of cheese","extra":"Buckets of cheese lấy từ lời hát chế của Cat.","forms":[],"before":false,"explain":"Câu cảm thán chế, kiểu “Trời đất ơi!”. “Holy …!” dùng để tỏ ra rất ngạc nhiên.","lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"}]$row$::jsonb) on conflict do nothing;
  insert into el_line_subs ("lang", "text", "start_ms", "lesson_id") select "lang", "text", "start_ms", "lesson_id" from jsonb_populate_recordset(null::el_line_subs, $row$[{"lang":"vi-VN","text":"Ê, mình đi mua thêm mấy món hay ho đi.","start_ms":500,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Thôi. Tớ không đủ tiền mua đồ mới đâu.","start_ms":3000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Thì tớ trả cho.","start_ms":6000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Trả bằng gì?","start_ms":8400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Bằng cái này.","start_ms":10000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Hả? Cậu lấy đâu ra **xấp tiền** dày cộp đó?","start_ms":11400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Từ cây ATM.","start_ms":14800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Cậu ấy phải nói mấy lần nữa hả?","start_ms":17700,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Vậy cậu muốn hỏi tiếp,","start_ms":20000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"hay muốn đi mua thêm đồ hay ho?","start_ms":22200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Này, tớ chỉ muốn chắc là đồ đó phải hay ho.","start_ms":24600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Mà, ừm, mình ghé cây ATM của cậu trước được không?","start_ms":29000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Được, nếu cậu muốn. Ồ!","start_ms":31700,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Chào mọi người, sao rồi?","start_ms":33800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Này, cậu, ừm, trông hộ bọn tớ hai đứa nhỏ này nhé?","start_ms":36400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Ôi, tớ không được.","start_ms":39600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Hai đứa muốn sờ chỏm tóc của anh không?","start_ms":45900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Có chứ, muốn mà.","start_ms":48500,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Này!","start_ms":56600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Gì ạ?","start_ms":62500,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Trong mấy tấm này, tấm nào trông anh quyến rũ?","start_ms":63800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tấm này? Không. Ghê quá.","start_ms":66300,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tấm này? Ghê. Không.","start_ms":68600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tấm này? Ọe. Tấm này? Eo ơi.","start_ms":71400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Để anh chụp thêm **ảnh tự sướng**.","start_ms":74200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Vậy đây là cây ATM của cậu?","start_ms":78500,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"{{Yarp}}.","start_ms":80800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Nhưng cậu làm gì có **tài khoản ngân hàng**.","start_ms":81900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Không có.","start_ms":84200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Thế cậu làm sao có thẻ ATM?","start_ms":84900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tớ đâu có thẻ ATM.","start_ms":86800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Vậy cậu rút tiền từ cây ATM kiểu gì?","start_ms":88600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"{{Mấy cái âm}}.","start_ms":92200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Mấy cái âm. Được rồi, nãy giờ cứ nói “mấy cái âm”,","start_ms":93500,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"mà tớ vẫn chẳng hiểu “mấy cái âm” là gì.","start_ms":95400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Bấm nút đi.","start_ms":97100,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Thấy chưa, mỗi lần cậu bấm một trong mấy","start_ms":102100,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"nút số đó là nghe một tiếng **bíp**.","start_ms":105400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Và đó là tin động trời trong cái não thỏ của cậu hả?","start_ms":108400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"À, đúng rồi, vì, cậu biết đấy,","start_ms":111000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"tớ chợt nhớ tới bài hát cũ đó,","start_ms":113400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"♪ (Cat hát lời tự chế: tầng hầm, mấy cái xô, phô mai) ♪","start_ms":115400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Khoan, khoan. Không, không, không. Cái gì?","start_ms":121400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Bài đó là {{“Take Me Out to the Ball Game”}}.","start_ms":123400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Hả?","start_ms":125900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"♪ (Sam hát đoạn mở đầu đúng lời) ♪","start_ms":127300,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"**Lời bài hát** đó chẳng có nghĩa gì cả.","start_ms":133400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Mà thôi! À, tớ tự hỏi liệu mình có chơi được","start_ms":135900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"bài đó bằng mấy nút số này không. Xem nhé?","start_ms":139200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"♪ (Cat bấm giai điệu trên bàn phím) ♪","start_ms":143000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Thấy chưa? 400 **đô**.","start_ms":152100,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"{{Ôi mấy xô phô mai ơi!}}","start_ms":154500,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Cô ấy vừa nói gì thế?","start_ms":156500,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Không có gì. Anh chụp tiếp đi.","start_ms":158300,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tuyệt! Anh mê tự sướng lắm.","start_ms":160800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Cậu làm vậy bao nhiêu lần rồi?","start_ms":162800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tớ không biết, chắc hai ba lần...","start_ms":165000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"mỗi ngày.","start_ms":167400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Cái gì?","start_ms":168800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Nghe này,","start_ms":170400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"cậu không được kể chuyện này với ai.","start_ms":173900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Sao thế?","start_ms":176600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Đâu phải **ăn cắp**.","start_ms":177900,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tớ chỉ chơi một bài, rồi cái máy cảm ơn tớ bằng tiền mặt.","start_ms":179600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Tớ biết, nhưng... tớ không chắc chuyện này **hợp pháp**.","start_ms":183400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Ồ. Vậy tớ trả lại nhé?","start_ms":188800,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Ờ, tớ đâu có nói thế.","start_ms":191600,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Vậy mình nên làm gì?","start_ms":194200,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"Theo tớ, mình cứ suy nghĩ","start_ms":196000,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"},{"lang":"vi-VN","text":"trong lúc đi mua đồ ở trung tâm thương mại.","start_ms":199400,"lesson_id":"7c97feca-802f-45ef-b51b-5691d41017a3"}]$row$::jsonb) on conflict do nothing;
end $do$;

-- el_lessons 913040d6-6064-4b26-8f3d-d4c6318f1b4d: Roar: hết nhịn rồi, tới lúc lên tiếng
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"39c4f5c6-dc35-4b25-89c7-92d4cd364eaa","title":"Katy Perry - Roar ( Slowed + Reverb )","status":"published","transcript":[{"end":9770,"text":"I used to bite my tongue and hold my breath","start":6650},{"end":12870,"text":"Scared to rock the boat and make a mess","start":10220},{"end":18550,"text":"So I sat quietly, agreed politely","start":12870},{"end":22100,"text":"I guess that I forgot I had a choice","start":19000},{"end":25210,"text":"I let you push me past the breaking point","start":22100},{"end":30760,"text":"I stood for nothing, so I fell for everything","start":25210},{"end":33770,"text":"You held me down, but I got up","start":30760},{"end":36900,"text":"Already brushing off the dust","start":34880},{"end":40060,"text":"You hear my voice, you hear that sound","start":36900},{"end":43140,"text":"Like thunder gonna shake the ground","start":40460},{"end":46250,"text":"You held me down, but I got up","start":43140},{"end":49110,"text":"Get ready 'cause I've had enough","start":46250},{"end":52590,"text":"I see it all, I see it now","start":49110},{"end":60900,"text":"I got the eye of the lion, a fighter, dancing through the fire","start":53070},{"end":68980,"text":"'Cause I am a champion and you're gonna hear me roar","start":60890},{"end":73190,"text":"Louder, louder than a lion","start":68720},{"end":81090,"text":"'Cause I am a champion and you're gonna hear me roar","start":73190},{"end":83270,"text":"Oh oh oh oh oh oh","start":81850},{"end":86180,"text":"Oh oh oh oh oh oh","start":83790},{"end":93120,"text":"You're gonna hear me roar","start":89400},{"end":98830,"text":"Now I'm floating like a butterfly","start":95830},{"end":101630,"text":"Stinging like a bee I earned my stripes","start":98830},{"end":107210,"text":"I went from zero, to my own hero","start":101630},{"end":110450,"text":"You held me down, but I got up","start":107210},{"end":113550,"text":"Already brushing off the dust","start":111020},{"end":116950,"text":"You hear my voice, you hear that sound","start":113550},{"end":119550,"text":"Like thunder gonna shake the ground","start":116950},{"end":122900,"text":"You held me down, but I got up","start":120050},{"end":125820,"text":"Get ready 'cause I've had enough","start":123370},{"end":129290,"text":"I see it all, I see it now","start":125820},{"end":137430,"text":"I got the eye of the tiger, a fighter, dancing through the fire","start":129690},{"end":145270,"text":"'Cause I am a champion and you're gonna hear me roar","start":137430},{"end":150000,"text":"Louder, louder than a lion","start":145270},{"end":157850,"text":"'Cause I am a champion and you're gonna hear me roar","start":150000},{"end":159910,"text":"Oh oh oh oh oh oh","start":157850},{"end":162860,"text":"Oh oh oh oh oh oh","start":160480},{"end":164880,"text":"Oh oh oh oh oh oh","start":164220},{"end":169790,"text":"You're gonna hear me roar","start":166310},{"end":172150,"text":"Oh oh oh oh oh oh","start":169790},{"end":175070,"text":"Oh oh oh oh oh oh","start":172720},{"end":178110,"text":"Oh oh oh oh oh oh","start":176460},{"end":182470,"text":"You'll gonna hear me roar","start":178110},{"end":207890,"text":"I got the eye of the tiger, a fighter, dancing through the fire","start":200120},{"end":216090,"text":"'Cause I am a champion and you're gonna hear me roar","start":207890},{"end":220270,"text":"Louder, louder than a lion","start":216090},{"end":228220,"text":"'Cause I am a champion and you're gonna hear me roar","start":220270},{"end":230380,"text":"Oh oh oh oh oh oh","start":228220},{"end":233520,"text":"Oh oh oh oh oh oh","start":230380},{"end":236540,"text":"Oh oh oh oh oh oh","start":233520},{"end":240420,"text":"You're gonna hear me roar","start":236540},{"end":242630,"text":"Oh oh oh oh oh oh","start":240420},{"end":245920,"text":"Oh oh oh oh oh oh","start":242630}],"channel_name":"Your Depression Clinic","date_created":"2026-11-23T0