  insert into el_lessons select (jsonb_populate_record(null::el_lessons, $row${"id":"913040d6-6064-4b26-8f3d-d4c6318f1b4d","note":null,"sort":400,"intro":"Roar của Katy Perry, bản chậm có vang. Nghe hết rồi trả lời vài câu nhẹ nhàng nha.","level":4,"title":"Roar: hết nhịn rồi, tới lúc lên tiếng","topic":"entertainment_celebrity","end_ms":245000,"status":"draft","explore":["Sư tử, hổ rồi tiếng gầm trong bài đều ý nói một chuyện: nín nhịn lâu quá rồi, giờ dám lên tiếng.","Đoạn có con bướm với con ong là nhắc tới câu nói nổi tiếng của võ sĩ quyền Anh Muhammad Ali."],"summary":"Katy kể hồi trước toàn cắn răng chịu, người ta nói gì cũng nghe cho yên chuyện. Tới lúc chịu hết nổi, Katy đứng dậy, dám nói điều mình nghĩ và tự tin như một nhà vô địch.","short_id":"16dbe2cb","start_ms":6200,"is_premium":false,"listen_for":"Cuối bài Katy khác hồi đầu ra sao?","date_created":"2026-11-25T11:36:57.017199+00:00","date_updated":"2026-11-26T07:26:05.396044+00:00","source_video_id":"39c4f5c6-dc35-4b25-89c7-92d4cd364eaa"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
