insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"1aba69c9-57d6-4ad7-aebf-3b153d745950","title":"kelly clarkson - stronger (slowed and reverb)","status":"published","transcript":[{"end":15210,"text":"You know the bed feels warmer","start":9870},{"end":20110,"text":"Sleeping here alone","start":15210},{"end":25190,"text":"You know I dream in color","start":20110},{"end":30290,"text":"And do the things I want","start":25190},{"end":33090,"text":"You think you got the best of me","start":30290},{"end":35820,"text":"Think you've had the last laugh","start":33090},{"end":40490,"text":"Bet you think that everything good is gone","start":35820},{"end":43230,"text":"Think you left me broken down","start":40490},{"end":45620,"text":"Think that I'd come running back","start":43230},{"end":50380,"text":"Baby you don't know me, 'cause you're dead wrong","start":45620},{"end":54070,"text":"What doesn't kill you makes you stronger","start":50380},{"end":56500,"text":"Stand a little taller","start":54070},{"end":60690,"text":"Doesn't mean I'm lonely when I'm alone","start":56500},{"end":64010,"text":"What doesn't kill you makes a fighter","start":60690},{"end":66670,"text":"Footsteps even lighter","start":64010},{"end":70790,"text":"Doesn't mean I'm over 'cause you're gone","start":66670},{"end":77230,"text":"What doesn't kill you makes you stronger, stronger","start":70790},{"end":80790,"text":"Just me, myself and I","start":77230},{"end":83920,"text":"What doesn't kill you makes you stronger","start":80790},{"end":86480,"text":"Stand a little taller","start":83920},{"end":90800,"text":"Doesn't mean I'm lonely when I'm alone","start":86620},{"end":102440,"text":"You heard that I was starting over with someone new","start":90800},{"end":112530,"text":"They told you I was moving on, over you","start":102440},{"end":115470,"text":"You didn't think that I'd come back","start":112530},{"end":117930,"text":"I'd come back swinging","start":115470},{"end":120910,"text":"You try to break me, but you see","start":117930},{"end":123850,"text":"What doesn't kill you makes you stronger","start":120910},{"end":126310,"text":"Stand a little taller","start":123850},{"end":130670,"text":"Doesn't mean I'm lonely when I'm alone","start":126310},{"end":133800,"text":"What doesn't kill you makes a fighter","start":130670},{"end":136350,"text":"Footsteps even lighter","start":133800},{"end":140530,"text":"Doesn't mean I'm over 'cause you're gone","start":136350},{"end":146960,"text":"What doesn't kill you makes you stronger, stronger","start":140530},{"end":150660,"text":"Just me, myself and I","start":146960},{"end":153700,"text":"What doesn't kill you makes you stronger","start":150660},{"end":156190,"text":"Stand a little taller","start":153700},{"end":160970,"text":"Doesn't mean I'm lonely when I'm alone","start":156190},{"end":168000,"text":"Thanks to you, I got a new thing started","start":160970},{"end":172710,"text":"Thanks to you, I'm not the broken-hearted","start":168000},{"end":177010,"text":"Thanks to you, I'm finally thinking about me","start":172710},{"end":185300,"text":"You know in the end, the day you left was just my beginning","start":177010},{"end":189850,"text":"In the end","start":185300},{"end":193700,"text":"What doesn't kill you makes you stronger","start":189850},{"end":196140,"text":"Stand a little taller","start":193700},{"end":200360,"text":"Doesn't mean I'm lonely when I'm alone","start":196140},{"end":203560,"text":"What doesn't kill you makes a fighter","start":200360},{"end":206300,"text":"Footsteps even lighter","start":203560},{"end":210340,"text":"Doesn't mean I'm over 'cause you're gone","start":206300},{"end":216770,"text":"What doesn't kill you makes you stronger, stronger","start":210340},{"end":220400,"text":"Just me, myself and I","start":216770},{"end":223630,"text":"What doesn't kill you makes you stronger","start":220400},{"end":226110,"text":"Stand a little taller","start":223630},{"end":231000,"text":"Doesn't mean I'm lonely when I'm alone","start":226110},{"end":236660,"text":"What doesn't kill you makes you stronger, stronger","start":231000},{"end":240320,"text":"Just me, myself and I","start":236660},{"end":243600,"text":"What doesn't kill you makes you stronger","start":240320},{"end":246030,"text":"Stand a little taller","start":243600},{"end":251320,"text":"Doesn't mean I'm lonely when I'm alone","start":246030},{"end":256520,"text":"When I'm alone","start":251320}],"channel_name":"GrifPer","date_created":"2026-11-23T08:22:47.077+00:00","date_updated":null,"yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi_webp/quH4VIrLmy0/sddefault.webp","transcript_kind":"manual","transcript_lang":"en","youtube_video_id":"quH4VIrLmy0","transcript_updated_at":"2026-11-23T08:22:47.068+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = 'quH4VIrLmy0') on conflict do nothing;
