-- el_lessons bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6: Tung hứng lửa ngay trước mặt mà không ai thèm nhìn?!
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"4b648466-e2ae-5d3d-a7cb-ba8120939d53","title":"Sam & Cat | Brain Crush | Nickelodeon UK","status":"published","transcript":[{"end":4400,"text":"Enjoy the party!","start":200},{"end":7600,"text":"Come on, I'm gonna go put my present for Otis","start":4500},{"end":11000,"text":"on the table with all the other ones.","start":7700},{"end":15000,"text":"I can't believe you didn't get Otis a present.","start":12400},{"end":16900,"text":"I did! See?","start":15000},{"end":21600,"text":"The card says right here, \"From Uncle George\"...","start":17000},{"end":25000,"text":"and Sam.","start":21700},{"end":29000,"text":"Come on.","start":25800},{"end":34200,"text":"Kind of a boring birthday party.","start":32000},{"end":36500,"text":"I'll say. Poor Otis.","start":34200},{"end":39600,"text":"Well, wait till Otis sees us. He loves us.","start":36600},{"end":42900,"text":"Oh, there's Otis! Oh, yeah.","start":39600},{"end":46500,"text":"Otis, my man!","start":43000},{"end":50400,"text":"What was that?","start":48600},{"end":52400,"text":"I give the kid a big friendly \"hey\",","start":50400},{"end":55500,"text":"and all I get is...","start":52500},{"end":59000,"text":"I don't even understand this birthday party.","start":55900},{"end":61600,"text":"Why aren't the children talking to each other?","start":59000},{"end":65400,"text":"Whoa, level 44!","start":61700},{"end":68700,"text":"I won 44!","start":65400},{"end":71400,"text":"Oh, they're playing Brain Crush.","start":68800},{"end":72800,"text":"Oh, yeah, of course.","start":71400},{"end":74400,"text":"What's Brain Crush?","start":72800},{"end":76200,"text":"You don't know much, do you?","start":74400},{"end":77300,"text":"Dice.","start":76200},{"end":79900,"text":"Brain Crush is this new game that every kid on earth is playing.","start":77400},{"end":81100,"text":"Not just kids.","start":79900},{"end":83200,"text":"Well, how come I never heard of Brain Crush?","start":81200},{"end":86900,"text":"Uh, probably because they don't write about it in Elderly Magazine.","start":83200},{"end":89100,"text":"Sam,","start":86900},{"end":92800,"text":"you know I don't appreciate your comments about how elderly people are","start":89200},{"end":96900,"text":"not with it. I'm with it.","start":92900},{"end":99300,"text":"Wait. You guys know that you can use your","start":97000},{"end":103000,"text":"phone to take a picture?","start":99400},{"end":106000,"text":"I can't defend you anymore.","start":103200},{"end":109700,"text":"Hey, kids! It's me,","start":106000},{"end":114200,"text":"Juggles! Yeah!","start":109800},{"end":119700,"text":"He juggled for the Vice President.","start":114300},{"end":124100,"text":"Okay, kids, you see these three wigs on a stick?","start":119800},{"end":128000,"text":"Well, check this out.","start":124200},{"end":136000,"text":"Now watch Juggles go!","start":132000},{"end":141000,"text":"Oh, my stars, look at those whirling wigs!","start":138600},{"end":143300,"text":"Look at the kids. They're not even","start":141000},{"end":147100,"text":"watching.","start":143400},{"end":150100,"text":"Nope, because they're all obsessed with Brain Crush.","start":147200},{"end":153600,"text":"Hey! Hey, look at me! I'm juggling flaming wigs!","start":150200},{"end":160000,"text":"See me!","start":156800},{"end":165100,"text":"Not one kid is even watching him. This is sad.","start":161400},{"end":168900,"text":"Hey, kids! Kids! Hey!","start":165200},{"end":172000,"text":"There is a man right there juggling for your entertainment.","start":169000},{"end":173900,"text":"He's worked his whole life for this.","start":172000},{"end":177600,"text":"Yeah, give the guy a break. He probably","start":174000},{"end":180400,"text":"still lives with his mother in her basement.","start":177700},{"end":183600,"text":"He's probably never dated a woman.","start":180500},{"end":186600,"text":"Uh, Juggles can hear you.","start":183600},{"end":191600,"text":"All these kids care about is playing the dumb game.","start":188600},{"end":194700,"text":"It's terrible. Oh,","start":191700},{"end":197300,"text":"here comes the birthday cake. That'll get their attention.","start":194800},{"end":209000,"text":"♪ (a birthday song) ♪","start":197400},{"end":214700,"text":"What, kids? Cake!","start":212200},{"end":217200,"text":"Who wants cake? They don't even want cake? Oh, come on.","start":214800},{"end":219800,"text":"Nobody wants cake?","start":217200},{"end":223000,"text":"Hi.","start":219800},{"end":230000,"text":"Let me help you out here.","start":223000}],"channel_name":"Nickelodeon UK","date_created":"2026-11-26T05:20:00.16592+00:00","date_updated":"2026-11-26T05:20:00.16592+00:00","yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi/LB1KUXMuvOQ/hqdefault.jpg","transcript_kind":"asr","transcript_lang":"en","youtube_video_id":"LB1KUXMuvOQ","transcript_updated_at":"2026-11-26T05:20:00.16592+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = 'LB1KUXMuvOQ') on conflict do nothing;
