  insert into el_lessons select (jsonb_populate_record(null::el_lessons, $row${"id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6","note":null,"sort":500,"intro":"Một bữa tiệc sinh nhật có quà, có bánh, có cả màn múa lửa, vậy mà im lặng đến lạ. Chuyện gì đã “bắt cóc” hết bọn trẻ?","level":5,"title":"Tung hứng lửa ngay trước mặt mà không ai thèm nhìn?!","topic":"film_story","end_ms":231000,"status":"draft","explore":["Vì sao buồn cười? Màn diễn càng hoành tráng, bọn trẻ càng dửng dưng. Người lớn muốn tỏ ra sành điệu thì lại lòi ra là lạc hậu. Sam mắng bọn trẻ để bênh chú diễn viên nhưng toàn nói những câu làm chú đau thêm. Cuối cùng, thứ không ai cần lại đúng là thứ Sam thèm nhất: chiếc bánh.","Tên “Brain Crush” gợi nhớ Candy Crush Saga, trò chơi điện thoại ra mắt năm 2012 và từng khiến rất nhiều người chơi quên cả xung quanh."],"summary":"Sam và Cat tới dự sinh nhật Otis, Sam “tặng quà” bằng cách ghi thêm tên mình vào quà của người khác. Bữa tiệc im lìm, Otis cũng chẳng chào ai vì cả đám đang mê trò Brain Crush trên điện thoại. Nona cãi rằng người già vẫn theo kịp thời đại rồi khoe điện thoại chụp được ảnh. Chú Juggles tung hứng tóc giả bốc lửa nhưng không đứa nào xem. Đến bánh sinh nhật cũng không ai muốn ăn, và Sam vui vẻ “giúp một tay”.","short_id":"d0f90959","start_ms":0,"is_premium":false,"listen_for":"Vì sao bọn trẻ không buồn xem màn biểu diễn?","date_created":"2026-11-26T05:20:18.237068+00:00","date_updated":"2026-11-26T05:20:18.237068+00:00","source_video_id":"4b648466-e2ae-5d3d-a7cb-ba8120939d53"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
