ột cơ hội, rồi nói toàn lời phũ","Khen chú diễn hay nhất trong các bữa tiệc","Bắt bọn trẻ trả tiền cho tiết mục của chú"],"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6","answer_end":183600,"segment_id":"b88e4226-18c2-4549-b2fc-29084fb3a28c","answer_start":174000},{"n":5,"id":"f21439ca-84cd-4f4e-aae0-3380e552da98","kind":"gist","answer":1,"prompt":"Khi không đứa nào chịu ăn bánh, chuyện gì xảy ra?","explain":"“Let me help you out here.”","options":["Cô bưng bánh tức giận tịch thu hết điện thoại","Có người xin được giúp một tay với cái bánh","Bọn trẻ đổi ý khi nghe hát mừng thêm lần nữa"],"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6","answer_end":227000,"segment_id":"b88e4226-18c2-4549-b2fc-29084fb3a28c","answer_start":223000},{"n":6,"id":"c0ed1a11-fda3-41d0-b573-f4c1f4ff8c21","kind":"why","answer":2,"prompt":"Vì sao bọn trẻ không buồn xem màn biểu diễn?","explain":"“They’re all obsessed with Brain Crush.”","options":["Vì đứa nào cũng đã xem tiết mục đó nhiều lần","Vì đứa nào cũng đang nóng lòng đợi cắt bánh","Vì đứa nào cũng đang dán mắt vào một trò chơi"],"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6","answer_end":150100,"segment_id":null,"answer_start":147200}]$row$::jsonb) on conflict do nothing;
  insert into el_vocab ("n", "id", "kind", "term", "forms", "at_end", "meaning", "at_start", "lesson_id") select "n", "id", "kind", "term", "forms", "at_end", "meaning", "at_start", "lesson_id" from jsonb_populate_recordset(null::el_vocab, $row$[{"n":1,"id":"60202478-29cc-4ba3-a105-092f3abc5267","kind":"word","term":"appreciate","forms":[],"at_end":89600,"meaning":"ở đây: thích, hoan nghênh","at_start":89400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":2,"id":"0dd7428c-ee1a-4917-81e6-159880c1b11f","kind":"word","term":"elderly","forms":[],"at_end":89800,"meaning":"lớn tuổi, già","at_start":89600,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":3,"id":"2df767cc-c44b-4125-b012-5755045d072d","kind":"word","term":"defend","forms":[],"at_end":103600,"meaning":"bênh vực, bảo vệ","at_start":103400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":4,"id":"dd6806a0-6903-4678-abf2-24fe5ab3768e","kind":"word","term":"juggling","forms":["juggle","juggled"],"at_end":150600,"meaning":"tung hứng","at_start":150400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":5,"id":"12f79be3-f013-4c2a-bf71-6a828272caeb","kind":"phrase","term":"obsessed with","forms":["obsessed"],"at_end":147600,"meaning":"mê mẩn, ám ảnh với","at_start":147400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":6,"id":"c080e12a-6870-495c-a330-49e211ddc018","kind":"word","term":"entertainment","forms":[],"at_end":169500,"meaning":"sự giải trí","at_start":169300,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":7,"id":"9ed5692d-153d-4c15-8171-e12db7b6117f","kind":"word","term":"basement","forms":[],"at_end":178200,"meaning":"tầng hầm","at_start":178000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"}]$row$::jsonb) on conflict do nothing;
  insert into el_notes ("n", "id", "kind", "term", "extra", "forms", "before", "explain", "lesson_id") select "n", "id", "kind", "term", "extra", "forms", "before", "explain", "lesson_id" from jsonb_populate_recordset(null::el_notes, $row$[{"n":1,"id":"ec3e8cf4-7fa3-4058-bd0d-c0a2d545c97e","kind":"culture","term":"Brain Crush","extra":null,"forms":[],"before":false,"explain":"Trò chơi điện thoại hư cấu trong phim.","lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":2,"id":"eb738fb8-92cf-43f9-a802-1fcd802ebcbc","kind":"idiom","term":"with it","extra":null,"forms":["not with it"],"before":false,"explain":"“Be with it” là bắt kịp thời đại, sành sỏi.","lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":3,"id":"10057cbc-2e6c-4321-87aa-a39880d1dcdc","kind":"idiom","term":"my man","extra":null,"forms":[],"before":false,"explain":"Cách gọi thân mật, kiểu “anh bạn”.","lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":4,"id":"6bd246bd-d0a7-453e-8bf3-0be4b7f8ee23","kind":"idiom","term":"Oh, my stars","extra":null,"forms":["my stars"],"before":false,"explain":"Câu cảm thán kiểu cũ, như “Trời đất ơi”. Hay nghe từ người lớn tuổi.","lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"n":5,"id":"97fa2f2d-9f66-4158-a202-3ddc6d1b5049","kind":"idiom","term":"give the guy a break","extra":null,"forms":[],"before":false,"explain":"“Give someone a break” là nương tay, cho người ta một cơ hội.","lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"}]$row$::jsonb) on conflict do nothing;
  insert into el_line_subs ("lang", "text", "start_ms", "lesson_id") select "lang", "text", "start_ms", "lesson_id" from jsonb_populate_recordset(null::el_line_subs, $row$[{"lang":"vi-VN","text":"Chúc dự tiệc vui vẻ!","start_ms":200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Đi nào, tớ đem quà của tớ cho Otis","start_ms":4500,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"để lên bàn cùng mấy món khác.","start_ms":7700,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Không tin nổi là cậu không mua quà cho Otis.","start_ms":12400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Có mà! Thấy chưa?","start_ms":15000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Thiệp ghi rõ đây này: “Từ chú George”...","start_ms":17000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"và Sam.","start_ms":21700,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Thôi nào.","start_ms":25800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Tiệc sinh nhật gì mà hơi chán.","start_ms":32000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Chuẩn luôn. Tội Otis.","start_ms":34200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Cứ đợi Otis thấy bọn mình đi. Nó quý bọn mình lắm.","start_ms":36600,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Ô, Otis kìa! Đúng rồi.","start_ms":39600,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Otis, {{anh bạn của tôi}}!","start_ms":43000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Cái gì vậy?","start_ms":48600,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Tôi chào thằng bé một tiếng “này” thật thân thiện,","start_ms":50400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"mà đáp lại chỉ có...","start_ms":52500,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Tôi chẳng hiểu nổi cái tiệc sinh nhật này.","start_ms":55900,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Sao bọn trẻ không nói chuyện với nhau?","start_ms":59000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Oa, màn 44!","start_ms":61700,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Tớ qua màn 44 rồi!","start_ms":65400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"À, tụi nó đang chơi {{Brain Crush}}.","start_ms":68800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Ừ, tất nhiên rồi.","start_ms":71400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Brain Crush là gì?","start_ms":72800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Bà chẳng biết gì mấy nhỉ?","start_ms":74400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Dice, nói đi.","start_ms":76200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Brain Crush là trò mới mà đứa trẻ nào trên đời cũng đang chơi.","start_ms":77400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Đâu chỉ trẻ con.","start_ms":79900,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Thế sao tôi chưa nghe tới Brain Crush bao giờ?","start_ms":81200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Ờ, chắc vì {{Tạp chí Người Cao Tuổi}} không viết về nó.","start_ms":83200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Sam,","start_ms":86900,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"cháu biết bà không **ưa** mấy lời cháu nói rằng **người già**","start_ms":89200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"không {{theo kịp thời đại}}. Bà theo kịp đấy.","start_ms":92900,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Khoan. Các cháu có biết là có thể dùng","start_ms":97000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"điện thoại để chụp ảnh không?","start_ms":99400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Cháu hết **bênh** nổi bà rồi.","start_ms":103200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Chào các bạn nhỏ! Chú đây,","start_ms":106000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Juggles! Yeah!","start_ms":109800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Chú ấy từng **tung hứng** cho Phó Tổng thống xem đấy.","start_ms":114300,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Nào các cháu, thấy ba bộ tóc giả trên cây gậy này chứ?","start_ms":119800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Vậy xem đây.","start_ms":124200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Giờ xem Juggles trổ tài!","start_ms":132000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"{{Trời đất ơi}}, nhìn mấy bộ tóc giả xoay tít kìa!","start_ms":138600,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Nhìn bọn trẻ đi. Tụi nó thậm chí","start_ms":141000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"không thèm xem.","start_ms":143400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Không, vì đứa nào cũng đang **mê mẩn** Brain Crush.","start_ms":147200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Này! Này, nhìn chú đi! Chú đang **tung hứng** tóc giả **bốc lửa** đây!","start_ms":150200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Nhìn chú đi mà!","start_ms":156800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Không một đứa nào xem chú ấy. Buồn thật.","start_ms":161400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Này mấy đứa! Mấy đứa! Này!","start_ms":165200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Có một người ngay kia đang tung hứng để mấy đứa **giải trí**.","start_ms":169000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Chú ấy khổ luyện cả đời vì chuyện này.","start_ms":172000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Đúng đấy, {{cho anh ta một cơ hội đi}}. Chắc anh ta","start_ms":174000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"vẫn còn ở với mẹ, dưới **tầng hầm** nhà bà ấy.","start_ms":177700,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Chắc cũng chưa hẹn hò cô nào bao giờ.","start_ms":180500,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Ờ, Juggles nghe thấy đấy.","start_ms":183600,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Bọn trẻ này chỉ quan tâm tới cái trò chơi ngớ ngẩn.","start_ms":188600,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Tệ thật. Ồ,","start_ms":191700,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"bánh sinh nhật ra rồi. Cái này chắc chắn khiến tụi nó chú ý.","start_ms":194800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"♪ (hát mừng sinh nhật) ♪","start_ms":197400,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Sao nào các con? Bánh đây!","start_ms":212200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Ai muốn ăn bánh? Tụi nó không thèm bánh luôn? Thôi nào.","start_ms":214800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Không ai muốn ăn bánh à?","start_ms":217200,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Chào cô.","start_ms":219800,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"},{"lang":"vi-VN","text":"Để cháu giúp cô một tay.","start_ms":223000,"lesson_id":"bcf08a42-d6eb-4b3e-ab4e-29573d3b3da6"}]$row$::jsonb) on conflict do nothing;
end $do$;

-- el_lessons 4b918488-d246-4cd1-ab86-50f72e409e2a: Lương gấp đôi để trông trẻ, nhìn “đứa bé” mà hết hồn?!
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"743da539-d9d6-57e6-826a-91e29a06479b","title":"Sam & Cat | Saturween | Nickelodeon UK","status":"published","transcript":[{"end":3400,"text":"Hey!","start":100},{"end":5000,"text":"I'm back. Where you been?","start":3400},{"end":7600,"text":"You were in the bathroom forever. Yeah, I decided to start","start":5000},{"end":10900,"text":"trick-or-treating early, in the girls' bathroom.","start":7700},{"end":13000,"text":"Uh-huh. I knocked on the stall doors.","start":11000},{"end":16400,"text":"Okay, I'm a little scared to ask this, but","start":13000},{"end":18200,"text":"what'd you get?","start":16500},{"end":20500,"text":"I got half a roll of toilet paper,","start":18200},{"end":24000,"text":"some dental floss,","start":20600},{"end":26000,"text":"and car keys.","start":24100},{"end":29000,"text":"Where were the car keys? Oh, on the bathroom floor. They bounced off my face","start":26000},{"end":32600,"text":"after the lady threw them at me.","start":29100},{"end":34400,"text":"Oh, we gotta go home. What's the rush?","start":32700},{"end":36300,"text":"Well, I have to get you in your Halloween","start":34400},{"end":41000,"text":"costume, and we have a babysitting job at 1:30. We're babysitting a kid today? Yeah.","start":36300},{"end":44000,"text":"But it's Saturday and it's Halloween.","start":41000},{"end":45800,"text":"Do you know what they call that?","start":44000},{"end":49500,"text":"Saturween! It only happens like once every 300 years.","start":45800},{"end":52300,"text":"Shouldn't that happen more like once","start":49600},{"end":54000,"text":"every seven years?","start":52300},{"end":56000,"text":"Oh, all of a sudden you're smart.","start":54000},{"end":59800,"text":"We only have to babysit one little girl from 1:30 to 5, and then we can have all","start":56100},{"end":64300,"text":"our Halloween fun. Saturween, whatever we want.","start":59800},{"end":68200,"text":"And since today is a holiday, I don't want to","start":64400},{"end":71000,"text":"babysit. We're getting paid double.","start":68200},{"end":74500,"text":"I like this plan.","start":71000},{"end":77500,"text":"Hi!","start":74900},{"end":80500,"text":"I'm Cat Valentine.","start":77600},{"end":84700,"text":"Simple things confuse me.","start":80500},{"end":86800,"text":"Ding dong!","start":84800},{"end":89200,"text":"You did my doorbell thing. What doorbell","start":86800},{"end":93500,"text":"thing? This is weird.","start":89300},{"end":96500,"text":"I'll get the door.","start":93600},{"end":99500,"text":"I'll chill. After you.","start":96500},{"end":105800,"text":"Hi! Hi!","start":103800},{"end":108100,"text":"I can't do it. So...","start":105800},{"end":112200,"text":"My name is Mr. Drange. Is this the","start":108200},{"end":118500,"text":"Sam and Cat Super Rockin' Fun-Time Babysitting Service?","start":112200},{"end":122000,"text":"Yep. Stand aside.","start":118600},{"end":129000,"text":"So, um, where is the kid you want us to babysit?","start":125000},{"end":131100,"text":"She's out in the hallway.","start":129000},{"end":135000,"text":"Come, Clarice.","start":131200},{"end":138700,"text":"She's shy.","start":135800},{"end":142000,"text":"I'll fetch her.","start":138800},{"end":146000,"text":"Where did you find this guy? At a flower shop?","start":143300},{"end":149700,"text":"Oh, by a graveyard. Ah.","start":146000},{"end":153800,"text":"This is my daughter, Clarice.","start":149800},{"end":157000,"text":"Clarice, meet Sam and Cat. Hey.","start":153800},{"end":165400,"text":"What's that, Clarice? No, they're not twins, but wouldn't that","start":161000},{"end":168600,"text":"be precious?","start":165500},{"end":171000,"text":"Uh, I thought you wanted us to babysit your","start":168700},{"end":173000,"text":"daughter. Indeed I do.","start":171000},{"end":177000,"text":"Cat, could you hold her carefully for a moment?","start":173000},{"end":184500,"text":"Here is a list of instructions you'll","start":181600},{"end":186900,"text":"need to follow as you look after Clarice.","start":184500},{"end":190000,"text":"Uh, this is a list of things you want us to","start":187000},{"end":194000,"text":"do for that?","start":190000},{"end":197000,"text":"For her. Yes.","start":194100},{"end":202000,"text":"Please read it out loud.","start":198300},{"end":206000,"text":"Taking turns.","start":203600},{"end":211800,"text":"Do not let Clarice become filthy.","start":209000},{"end":214800,"text":"But if she does become filthy, you must","start":211800},{"end":220400,"text":"bathe her. She enjoys the bath.","start":214900},{"end":224000,"text":"Your pay is double, right? Certainly.","start":220600},{"end":228000,"text":"Well, according to my pocket watch, it's time for me to take my leave.","start":224000},{"end":231300,"text":"Farewell.","start":228000},{"end":236000,"text":"Daddy loves you.","start":231400}],"channel_name":"Nickelodeon UK","date_created":"2026-11-26T05:22:24.804317+00:00","date_updated":"2026-11-26T05:22:24.804317+00:00","yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi/vgA3B_uId_s/hqdefault.jpg","transcript_kind":"asr","transcript_lang":"en","youtube_video_id":"vgA3B_uId_s","transcript_updated_at":"2026-11-26T05:22:24.804317+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = 'vgA3B_uId_s') on conflict do nothing;
do $do$
