    return;
  end if;
  
  insert into el_lessons select (jsonb_populate_record(null::el_lessons, $row${"id":"4b918488-d246-4cd1-ab86-50f72e409e2a","note":null,"sort":500,"intro":"Đúng Halloween, có ông khách lịch sự đến thuê trông con gái, trả hậu hĩnh. Nghe quá hời, cho tới lúc cô bé xuất hiện.","level":5,"title":"Lương gấp đôi để trông trẻ, nhìn “đứa bé” mà hết hồn?!","topic":"film_story","end_ms":236000,"status":"draft","explore":["Vì sao buồn cười? Cat coi nhà vệ sinh là chỗ xin kẹo và coi chìa khóa bị ném vào mặt là quà. Sam hóa trang thành chính bạn mình rồi nhại cả thói quen của bạn. Còn ông Drange càng nói năng lịch sự, nghiêm túc thì cảnh “con gái” là búp bê càng rợn mà buồn cười.","“Saturween” ghép Saturday với Halloween. Cat bảo 300 năm mới có một lần, nhưng thực ra 31/10 rơi vào thứ Bảy cứ khoảng 5 đến 11 năm một lần, ví dụ 2015 và 2020."],"summary":"Cat đi “xin kẹo” trong nhà vệ sinh và mang về toàn đồ kỳ quặc, rồi giục Sam về nhà hóa trang vì chiều nay có ca trông trẻ lương gấp đôi. Sam hóa trang thành Cat và bắt chước bạn. Ông Drange tới gõ cửa, giới thiệu con gái Clarice, hóa ra là một con búp bê. Ông trò chuyện với nó như người thật, đưa danh sách hướng dẫn, dặn không được để con bé bẩn và nếu bẩn thì phải tắm, rồi chào ra về.","short_id":"226dd31e","start_ms":0,"is_premium":false,"listen_for":"Ông khách dặn phải làm gì nếu Clarice bị bẩn?","date_created":"2026-11-26T05:22:41.03694+00:00","date_updated":"2026-11-26T05:22:41.03694+00:00","source_video_id":"743da539-d9d6-57e6-826a-91e29a06479b"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
