  insert into el_questions ("n", "id", "kind", "answer", "prompt", "explain", "options", "lesson_id", "answer_end", "segment_id", "answer_start") select "n", "id", "kind", "answer", "prompt", "explain", "options", "lesson_id", "answer_end", "segment_id", "answer_start" from jsonb_populate_recordset(null::el_questions, $row$[{"n":1,"id":"b4869780-812d-48e8-ae31-c452c6df4d1c","kind":"detail","answer":0,"prompt":"Cat đi “xin kẹo” trong nhà vệ sinh và được những gì?","explain":"“Half a roll of toilet paper, some dental floss, and car keys.”","options":["Giấy vệ sinh, chỉ nha khoa và chìa khóa xe","Khăn giấy, bàn chải đánh răng và một ít tiền","Kẹo sô-cô-la, kem đánh răng và chìa khóa nhà"],"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a","answer_end":26000,"segment_id":"e42fce0e-38c2-4f4e-bc23-6a2c75351723","answer_start":18200},{"n":2,"id":"0cf57a8a-522b-46d8-b536-74d922d940ee","kind":"why","answer":0,"prompt":"Điều gì khiến ca trông trẻ ngày lễ này đáng làm?","explain":"“We’re getting paid double.”","options":["Tiền công được trả gấp đôi ngày thường","Đứa trẻ sẽ được đi xin kẹo cùng hai cô","Phụ huynh tặng kèm hai bộ đồ hóa trang"],"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a","answer_end":71000,"segment_id":"e42fce0e-38c2-4f4e-bc23-6a2c75351723","answer_start":68200},{"n":3,"id":"50a268cc-1771-4a18-968d-4c747deb9106","kind":"detail","answer":2,"prompt":"Khi được hỏi đứa bé đâu, ông Drange trả lời thế nào?","explain":"“She’s out in the hallway… She’s shy.”","options":["Nó đang ngủ trên xe nên lát nữa mới lên","Nó đang đi xin kẹo và sắp quay về đến nơi","Nó đang đứng ngoài hành lang vì nhút nhát"],"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a","answer_end":138700,"segment_id":"bb2c014d-ecb9-4492-9a88-55fab97c29ab","answer_start":129000},{"n":4,"id":"94af4c6f-0e8c-4b5e-ab57-e9b6b91817b7","kind":"detail","answer":2,"prompt":"Ông Drange làm như thể Clarice vừa hỏi điều gì?","explain":"“No, they’re not twins, but wouldn’t that be precious?”","options":["Hai cô gái kia có được trả công gấp đôi không","Hai cô gái kia có biết cách tắm cho nó không","Hai cô gái kia có phải chị em sinh đôi không"],"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a","answer_end":168600,"segment_id":"e91496e9-e6b1-48a5-aad1-4fdc9d416683","answer_start":161000},{"n":5,"id":"c390c057-5cd8-4fa6-9260-12cb46d05e18","kind":"detail","answer":1,"prompt":"Ông khách dặn phải làm gì nếu Clarice bị bẩn?","explain":"“If she does become filthy, you must bathe her. She enjoys the bath.”","options":["Phải gọi ngay cho ông để ông đến đón","Phải tắm cho con bé, vì nó thích tắm","Phải thay đồ mới, vì nó rất sợ nước"],"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a","answer_end":218000,"segment_id":null,"answer_start":211800}]$row$::jsonb) on conflict do nothing;
