  insert into el_notes ("n", "id", "kind", "term", "extra", "forms", "before", "explain", "lesson_id") select "n", "id", "kind", "term", "extra", "forms", "before", "explain", "lesson_id" from jsonb_populate_recordset(null::el_notes, $row$[{"n":1,"id":"a182eb84-e787-47d6-a12b-f37101d8d8d8","kind":"culture","term":"trick-or-treating","extra":null,"forms":["trick-or-treat"],"before":true,"explain":"Tục đêm Halloween: trẻ em mặc đồ hóa trang đi gõ cửa từng nhà xin kẹo.","lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"n":2,"id":"a19b271d-85db-4d15-8fb6-7faa24fee16b","kind":"culture","term":"Saturween","extra":null,"forms":[],"before":false,"explain":"Từ chế: Saturday + Halloween.","lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"n":3,"id":"651a19b7-ac69-47c3-a9df-f83d94296f44","kind":"idiom","term":"precious","extra":null,"forms":[],"before":false,"explain":"Ở đây là “đáng yêu quá”, giọng hơi làm điệu.","lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"n":4,"id":"34290bc6-f3c7-4fc9-a8ce-b59faaa67f4a","kind":"idiom","term":"take my leave","extra":null,"forms":[],"before":false,"explain":"Cách nói rất trang trọng, kiểu cổ, của “I have to go”.","lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"n":5,"id":"e2e5ee7c-1bf0-43ee-aa15-d56bb664a579","kind":"culture","term":"pocket watch","extra":null,"forms":[],"before":false,"explain":"Đồng hồ bỏ túi có dây xích, kiểu xưa.","lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"}]$row$::jsonb) on conflict do nothing;
  insert into el_line_subs ("lang", "text", "start_ms", "lesson_id") select "lang", "text", "start_ms", "lesson_id" from jsonb_populate_recordset(null::el_line_subs, $row$[{"lang":"vi-VN","text":"Này!","start_ms":100,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tớ về rồi đây. Cậu đi đâu vậy?","start_ms":3400,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Cậu ở trong nhà vệ sinh lâu muốn chết. Ừ, tớ quyết định bắt đầu","start_ms":5000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"{{đi xin kẹo}} sớm, ngay trong nhà vệ sinh nữ.","start_ms":7700,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Ừ hứ. Tớ gõ cửa từng buồng.","start_ms":11000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Rồi, tớ hơi sợ khi hỏi câu này, nhưng","start_ms":13000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"cậu xin được gì?","start_ms":16500,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tớ được nửa cuộn giấy vệ sinh,","start_ms":18200,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"ít **chỉ nha khoa**,","start_ms":20600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"và chìa khóa xe.","start_ms":24100,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Chìa khóa xe ở đâu ra? À, trên sàn nhà vệ sinh. Nó đập vào mặt tớ rồi nảy ra","start_ms":26000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"sau khi cô kia ném nó vào tớ.","start_ms":29100,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Ồ, mình phải về nhà thôi. Sao mà **vội** thế?","start_ms":32700,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Thì tớ phải giúp cậu mặc","start_ms":34400,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"**đồ hóa trang** Halloween, mà 1 giờ rưỡi mình có ca trông trẻ. Hôm nay mình trông trẻ á? Ừ.","start_ms":36300,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Nhưng hôm nay là thứ Bảy, lại là Halloween.","start_ms":41000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Cậu biết người ta gọi ngày đó là gì không?","start_ms":44000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"{{Saturween}}! Cỡ 300 năm mới có một lần.","start_ms":45800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Chẳng phải nó phải xảy ra khoảng","start_ms":49600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"bảy năm một lần chứ?","start_ms":52300,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Ồ, tự nhiên cậu thông minh đột xuất.","start_ms":54000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Mình chỉ phải trông một bé gái từ 1 rưỡi đến 5 giờ, rồi tha hồ","start_ms":56100,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"chơi Halloween. Saturween, muốn gì làm nấy.","start_ms":59800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Và vì hôm nay là ngày lễ, tớ chẳng muốn","start_ms":64400,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"trông trẻ. Mình được trả **gấp đôi** đấy.","start_ms":68200,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Kế hoạch này tớ chịu.","start_ms":71000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Chào!","start_ms":74900,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tớ là Cat Valentine.","start_ms":77600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Mấy chuyện đơn giản làm tớ rối trí.","start_ms":80500,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"{{Đing đoong}}!","start_ms":84800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Cậu bắt chước trò chuông cửa của tớ. Trò chuông cửa","start_ms":86800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"nào? Kỳ quá đi.","start_ms":89300,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Để tớ ra mở cửa.","start_ms":93600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tớ thong thả. Cậu trước đi.","start_ms":96500,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Chào! Chào!","start_ms":103800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tớ chịu thôi. Vậy...","start_ms":105800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tôi là ông Drange. Đây có phải","start_ms":108200,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Dịch Vụ Trông Trẻ Siêu Vui Siêu Chất của Sam và Cat?","start_ms":112200,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Đúng ạ. Tránh ra nào.","start_ms":118600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Vậy, ừm, đứa bé chú muốn tụi cháu trông đâu ạ?","start_ms":125000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Con bé đang ở ngoài **hành lang**.","start_ms":129000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Vào đi, Clarice.","start_ms":131200,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Con bé **nhút nhát**.","start_ms":135800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Để tôi ra dắt nó.","start_ms":138800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Cậu kiếm đâu ra ông này vậy? Ở tiệm hoa hả?","start_ms":143300,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"À, cạnh một **nghĩa địa**. À ra vậy.","start_ms":146000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Đây là con gái tôi, Clarice.","start_ms":149800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Clarice, chào Sam và Cat đi. Chào.","start_ms":153800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Gì cơ, Clarice? Không, hai cô ấy không phải sinh đôi, nhưng nếu thế thì","start_ms":161000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"{{đáng yêu}} biết mấy nhỉ?","start_ms":165500,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Ờ, cháu tưởng chú muốn tụi cháu trông","start_ms":168700,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"con gái chú. Đúng là vậy.","start_ms":171000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Cat, cháu bế con bé cẩn thận một lát được không?","start_ms":173000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Đây là danh sách **hướng dẫn** mà các cháu","start_ms":181600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"phải làm theo khi chăm Clarice.","start_ms":184500,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Ờ, đây là mấy việc chú muốn tụi cháu","start_ms":187000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"làm cho cái đó á?","start_ms":190000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Cho con bé. Đúng.","start_ms":194100,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Làm ơn đọc to lên.","start_ms":198300,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Thay phiên nhau.","start_ms":203600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Không được để Clarice **bẩn thỉu**.","start_ms":209000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Nhưng nếu con bé bị bẩn, các cháu phải","start_ms":211800,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"**tắm** cho nó. Nó thích tắm lắm.","start_ms":214900,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tiền công gấp đôi, đúng không ạ? Dĩ nhiên.","start_ms":220600,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Chà, theo {{đồng hồ quả quýt}} của tôi thì đã đến lúc tôi {{xin cáo từ}}.","start_ms":224000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Tạm biệt.","start_ms":228000,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"},{"lang":"vi-VN","text":"Bố yêu con.","start_ms":231400,"lesson_id":"4b918488-d246-4cd1-ab86-50f72e409e2a"}]$row$::jsonb) on conflict do nothing;
end $do$;

-- il_lessons 3fb72aa8-9f92-408e-b1c6-b26b71312916: Lá thư cuối dặn một người điều gì?
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"7ee7ebc2-01b8-468b-8d2a-cca78882a25a","title":"Me Before You - Louisa and Will - Photograph and Letter","status":"published","transcript":[{"end":19440,"text":"Loving can hurt","start":15600},{"end":24200,"text":"Loving can hurt sometimes","start":19440},{"end":31370,"text":"But it's the only thing that I know","start":23250},{"end":37930,"text":"When it gets hard","start":31370},{"end":42670,"text":"You know it can get hard sometimes","start":37930},{"end":51370,"text":"It is the only thing that makes us feel alive","start":42670},{"end":56920,"text":"We keep this love in a photograph","start":51370},{"end":61640,"text":"We made these memories for ourselves","start":56920},{"end":64050,"text":"Where our eyes are never closing","start":61640},{"end":66300,"text":"Hearts are never broken","start":64050},{"end":69680,"text":"Times forever frozen still","start":66300},{"end":72900,"text":"So you can keep me","start":69680},{"end":75300,"text":"Inside the pocket","start":72900},{"end":77480,"text":"Of your ripped jeans","start":75300},{"end":79580,"text":"Holdin' me closer","start":77480},{"end":82030,"text":"'Til our eyes meet","start":79580},{"end":86890,"text":"You won't ever be alone","start":82030},{"end":92770,"text":"Wait for me to come home","start":86890},{"end":95070,"text":"Loving can heal","start":92260},{"end":99990,"text":"Loving can mend your soul","start":95070},{"end":106770,"text":"And it's the only thing that I know (know)","start":97470},{"end":112940,"text":"I swear it will get easier","start":106770},{"end":117640,"text":"Remember that with every piece of ya","start":112940},{"end":126280,"text":"And it's the only thing we take with us when we die","start":117640},{"end":132080,"text":"We keep this love in this photograph","start":126280},{"end":136960,"text":"We made these memories for ourselves","start":132080},{"end":139310,"text":"Where our eyes are never closing","start":136960},{"end":141720,"text":"Our hearts were never broken","start":139310},{"end":145300,"text":"Times forever frozen still","start":141720},{"end":148540,"text":"So you can keep me","start":145300},{"end":150720,"text":"Inside the pocket","start":148540},{"end":153010,"text":"Of your ripped jeans","start":150720},{"end":155180,"text":"Holdin' me closer","start":153010},{"end":157300,"text":"'Til our eyes meet","start":155180},{"end":162510,"text":"You won't ever be alone","start":157300},{"end":166220,"text":"And if you hurt me","start":162510},{"end":170770,"text":"That's OK, baby, only words bleed","start":166220},{"end":175140,"text":"Inside these pages you just hold me","start":170770},{"end":179660,"text":"And I won't ever let you go","start":175140},{"end":198680,"text":"Wait for me to come home","start":179660},{"end":201870,"text":"Oh you can fit me","start":198680},{"end":206260,"text":"Inside the necklace you got when you were 16","start":201870},{"end":208410,"text":"Next to your heartbeat","start":206260},{"end":210610,"text":"Where I should be","start":208410},{"end":216750,"text":"Keep it deep within your soul","start":210610},{"end":219560,"text":"And if you hurt me","start":217490},{"end":224060,"text":"Well, that's OK, baby, only words bleed","start":219560},{"end":228370,"text":"Inside these pages you just hold me","start":224060},{"end":233800,"text":"And I won't ever let you go","start":228370},{"end":237340,"text":"When I'm away","start":233800},{"end":241770,"text":"I will remember how you kissed me","start":237340},{"end":244180,"text":"Under the lamppost","start":241770},{"end":246450,"text":"Back on 6th street","start":244180},{"end":250100,"text":"Hearing you whisper through the phone,","start":246450},{"end":254500,"text":"\"Wait for me to come home.\"","start":250100},{"end":259169,"text":"Clark, a few weeks should have passed by the time you read this.","start":254560},{"end":262430,"text":"If you followed the instructions, you'll be in Paris","start":259600},{"end":266129,"text":"on one of those chairs that never sit quite level on the pavement.","start":262720},{"end":267710,"text":"I hope it's still sunny.","start":266160},{"end":273889,"text":"Across the bridge to your right, you will see L'Artisan Parfumeur.","start":270240},{"end":276870,"text":"You should try the scent called Papillons Extrême.","start":274240},{"end":279190,"text":"I always did think it would smell great on you.","start":277040},{"end":287919,"text":"There are a few things I wanted to say and couldn't,","start":284639},{"end":291050,"text":"because you would have got all emotional and you wouldn't have let me finish.","start":287919},{"end":296410,"text":"So, here it is.","start":294080},{"end":303629,"text":"When you get back home, Michael Lawler will give you access to a bank account that contains enough to give you a new beginning.","start":297360},{"end":305520,"text":"Don't start panicking.","start":303759},{"end":310390,"text":"It's not enough for you to sit around for the rest of your life, but it should buy you your freedom.","start":305520},{"end":314590,"text":"Wear those stripy legs with pride.","start":312400},{"end":317690,"text":"Knowing you still have possibilities is a luxury.","start":314960},{"end":322890,"text":"Knowing I might have given them to you has eased something for me.","start":318479},{"end":326730,"text":"So, this is it.","start":324000},{"end":330720,"text":"You are scored on my heart, Clark.","start":327600},{"end":332720,"text":"You were from the first day you walked in","start":330720},{"end":336880,"text":"with your sweet smile and your ridiculous clothes and your bad jokes","start":332720},{"end":340609,"text":"and your complete inability to ever hide a single thing you felt.","start":336880},{"end":344430,"text":"Don't think of me too often.","start":342720},{"end":346710,"text":"I don't want you getting sad.","start":345120},{"end":348609,"text":"Just live well.","start":347360},{"end":351329,"text":"Just live.","start":350240},{"end":355510,"text":"I'll be walking beside you every step of the way.","start":353039},{"end":358770,"text":"Love, Will.","start":357440}],"channel_name":"Christopher Shaw","date_created":"2026-11-23T07:29:59.792+00:00","date_updated":null,"yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi_webp/xY207AovuMY/sddefault.webp","transcript_kind":"manual","transcript_lang":"en","youtube_video_id":"xY207AovuMY","transcript_updated_at":"2026-11-23T07:35:27.030508+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = 'xY207AovuMY') on conflict do nothing;
do $do$
