  insert into video_tags select (jsonb_populate_record(null::video_tags, $row${"wpm":78.2,"note":null,"ai_at":"2026-11-23T07:30:03.636+00:00","level":1,"score":2.14,"topic":null,"broken":false,"ai_error":null,"ai_topic":"film_story","ai_reason":"Video là cảnh phim Me Before You giữa Louisa và Will, kèm bài hát Photograph và lá thư.","level_why":"nói chậm (78 từ/phút); Cảnh phim / series: sub không ghi ai nói, khó hơn số liệu","subtopics":null,"duration_s":344,"rare_ratio":0.054,"signals_at":"2026-11-23T07:29:59.842+00:00","word_count":299,"editor_pick":false,"known_ratio":0.946,"noise_ratio":0,"ai_subtopics":["relationships"],"content_type":null,"date_updated":"2026-11-23T07:29:59.842+00:00","level_manual":null,"speech_ratio":0.668,"ai_confidence":"high","avg_cue_words":5.4,"speaker_turns":0,"ai_content_type":"film_scene","source_video_id":"7ee7ebc2-01b8-468b-8d2a-cca78882a25a"}$row$::jsonb || jsonb_build_object('source_video_id', v))).* on conflict do nothing;
  insert into il_lessons select (jsonb_populate_record(null::il_lessons, $row${"id":"3fb72aa8-9f92-408e-b1c6-b26b71312916","note":null,"slug":"wills-letter-to-clark","sort":0,"focus":"linking","intro":"Có những lời người ta chỉ kịp viết ra. Đây là phần cuối một lá thư trong phim Me Before You.","level":1,"title":"Lá thư cuối dặn một người điều gì?","topic":null,"end_ms":355510,"status":"published","explore":"## Bộ phim\r\nMe Before You ra mắt năm 2016, dựa trên tiểu thuyết cùng tên của Jojo Moyes. Emilia Clarke đóng Louisa Clark, một cô gái vui tính nhận việc chăm sóc Will Traynor, chàng trai bị liệt sau một tai nạn. Will do Sam Claflin đóng.\r\n\r\n## Lá thư\r\nSau khi Will qua đời, Louisa đọc lá thư anh để lại tại một quán cà phê ở Paris, đúng như anh dặn. Anh nhắc đến khoản tiền giúp cô bắt đầu lại, và mong cô dám sống rộng hơn.\r\n\r\n## Cách nói đáng nhớ\r\n- \"Wear those stripy legs with pride\": cứ tự hào là chính mình, kể cả với đôi tất sọc.\r\n- \"You are scored on my heart\": hình bóng em đã khắc vào tim anh.\r\n- \"Just live well\": cứ sống thật tốt.\r\n\r\nVideo ghép đoạn thư này sau một bài hát, nên phần luyện nghe chỉ lấy đoạn đọc thư, nơi giọng nói rõ và chậm.","short_id":"c7a165a6","start_ms":303759,"is_premium":false,"gist_answer":0,"gist_prompt":"Người viết thư muốn người đọc làm gì?","date_created":"2026-11-25T11:31:17.337255+00:00","date_updated":"2026-11-25T11:34:30.883644+00:00","gist_explain":"Lá thư dặn đừng nghĩ về người viết quá nhiều, đừng buồn, cứ sống thật tốt.","gist_options":["Cứ sống thật tốt và đừng buồn vì mình","Hoảng lên và đi tìm mình ngay","Luôn nghĩ về mình mỗi khi thấy buồn"],"gist_sentences":[7,8,9],"source_video_id":"7ee7ebc2-01b8-468b-8d2a-cca78882a25a"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
  insert into il_sentences ("n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id") select "n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id" from jsonb_populate_recordset(null::il_sentences, $row$[{"n":1,"id":"44b40490-886e-413d-a019-29d8ba0186b8","sub":null,"part":1,"text":"Don't start panicking.","traps":[{"kind":"linking","note":"Âm t cuối don't gần mất trước start, nên dễ sót ý phủ định.","real":"/dəʊn stɑːt/ (nghe như \"đâun-START\")","text":"Don't start","skill":"t-d-dropping"}],"end_ms":305520,"start_ms":303759,"key_words":["dont"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":2,"id":"09b81f26-5070-40b3-bd13-d3fd01600dfa","sub":null,"part":1,"text":"Wear those stripy legs with pride.","traps":[],"end_ms":314590,"start_ms":312400,"key_words":["pride"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":3,"id":"3f01c4fb-b0f5-4280-ab6b-01c0af7528a5","sub":null,"part":1,"text":"Knowing you still have possibilities is a luxury.","traps":[],"end_ms":317690,"start_ms":314960,"key_words":["possibilities","luxury"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":4,"id":"9e4a5ec4-3cd7-4a38-94b6-6641e9dd03c5","sub":null,"part":1,"text":"Knowing I might have given them to you has eased something for me.","traps":[{"kind":"linking","note":"Âm t trong might đọc nhẹ thành đ rồi dính vào have đọc yếu.","real":"/ˈmaɪ ɾəv/ (nghe như \"MAI-đơv\")","text":"might have","skill":"flap-t"},{"kind":"linking","note":"Âm cuối của has nối sang eased, nghe như từ sau bắt đầu bằng z.","real":"/hə ˈziːzd/ (nghe như \"hơ-ZIZD\")","text":"has eased","skill":"linking-words"}],"end_ms":322890,"start_ms":318479,"key_words":["eased"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":5,"id":"e40f9169-04ee-45dc-ac0e-fdce572c213d","sub":null,"part":1,"text":"So, this is it.","traps":[],"end_ms":326730,"start_ms":324000,"key_words":[],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":6,"id":"e313b5cb-6fbe-4c26-b4d2-6f101f0f5609","sub":null,"part":1,"text":"You are scored on my heart, Clark.","traps":[{"kind":"linking","note":"Đuôi d của scored nối sang on, dễ nghe thành score on.","real":"/ˈskɔː dɒn/ (nghe như \"sko-ĐON\")","text":"scored on","skill":"linking-words"}],"end_ms":330720,"start_ms":327600,"key_words":["scored"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":7,"id":"62e94ca5-a724-46c7-9d5b-764fc3786fc6","sub":null,"part":1,"text":"Don't think of me too often.","traps":[{"kind":"linking","note":"Âm k của think nối sang of đọc yếu.","real":"/ˈθɪŋ kəv/ (nghe như \"THING-kơv\")","text":"think of","skill":"linking-words"}],"end_ms":344430,"start_ms":342720,"key_words":["dont"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":8,"id":"db93e119-b7af-4b9a-b7e1-edcb97584c4e","sub":null,"part":1,"text":"I don't want you getting sad.","traps":[{"kind":"linking","note":"Âm t gặp you biến thành ch.","real":"/ˈwɒn tʃu/ (nghe như \"WON-chu\")","text":"want you","skill":"yod-coalescence"}],"end_ms":346710,"start_ms":345120,"key_words":["sad"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":9,"id":"16c60b24-6cf3-426a-931c-ecd8650da929","sub":null,"part":1,"text":"Just live well.","traps":[],"end_ms":348609,"start_ms":347360,"key_words":["well"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":10,"id":"ba663065-c31b-44f8-8b12-57f5f0cb2454","sub":null,"part":1,"text":"Just live.","traps":[],"end_ms":351329,"start_ms":350240,"key_words":[],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":11,"id":"59008797-5e73-4a65-9339-764af9273259","sub":null,"part":1,"text":"I'll be walking beside you every step of the way.","traps":[{"kind":"linking","note":"Âm l của I'll rất mờ trước be, dễ nghe thành I be.","real":"/aɪl bi/ (nghe như \"ao-bi\")","text":"I'll be","skill":"contractions"}],"end_ms":355510,"start_ms":353039,"key_words":["beside"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"}]$row$::jsonb) on conflict do nothing;
  insert into il_translations ("key", "lang", "text", "lesson_id") select "key", "lang", "text", "lesson_id" from jsonb_populate_recordset(null::il_translations, $row$[{"key":"title","lang":"en-US","text":"What does a last letter ask someone to do?","lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"key":"intro","lang":"en-US","text":"Some things people only manage to write down. This is the end of a letter from the film Me Before You.","lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"key":"explore","lang":"en-US","text":"## The film\r\nMe Before You (2016) is based on the novel by Jojo Moyes. Emilia Clarke plays Louisa Clark, a cheerful young woman hired to care for Will Traynor, who was paralysed after an accident. Sam Claflin plays Will.\r\n\r\n## The letter\r\nAfter Will dies, Louisa reads the letter he left for her at a cafe in Paris, as he asked. He mentions the money that will help her start again and hopes she will live more boldly.\r\n\r\n## Lines worth keeping\r\n- \"Wear those stripy legs with pride\": be proud of who you are, striped tights and all.\r\n- \"You are scored on my heart\": you are carved into my heart.\r\n- \"Just live well\": simply live a good life.\r\n\r\nThe video places this letter after a song, so the practice uses only the spoken part, where the voice is clear and slow.","lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"}]$row$::jsonb) on conflict do nothing;
end $do$;

-- il_lessons d15579dc-1aca-4883-a327-b1e083d437e1: Tình yêu quá mãnh liệt có đáng lo không?
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"1b0dae7c-8011-416b-9ae9-c44896c9e3cf","title":"The difference between healthy and unhealthy love | Katie Hood | TED","status":"published","transcript":[{"end":15663,"text":"So when you think about a child, a close friend,","start":12475},{"end":20100,"text":"or a romantic partner, the word \"love\" probably comes to mind,","start":15663},{"end":24892,"text":"and instantly other emotions rush in: joy and hope,","start":20100},{"end":31558,"text":"excitement, trust and security, and yes, sometimes sadness and disappointment.","start":24892},{"end":35833,"text":"There might not be a word in the dictionary that more of us are connected to than love.","start":31558},{"end":39767,"text":"Yet, given its central importance in our lives,","start":37142},{"end":43417,"text":"isn't it interesting that we're never explicitly taught how to love?","start":39767},{"end":48517,"text":"We build friendships, navigate early romantic relationships,","start":44308},{"end":53292,"text":"get married and bring babies home from the hospital with the expectation that we'll figure it out.","start":48517},{"end":58350,"text":"But the truth is, we often harm and disrespect the ones we love.","start":54475},{"end":62558,"text":"It can be subtle things like guilting a friend into spending time with you","start":58350},{"end":68583,"text":"or sneaking a peak at your partner's texts or shaming a child for their lack of effort at school.","start":62558},{"end":77725,"text":"100 percent of us will be on the receiving end of unhealthy relationship behaviors and 100 percent of us will do unhealthy things.","start":69850},{"end":79333,"text":"It's part of being human.","start":77725},{"end":81586,"text":"In its worst form,","start":80683},{"end":85183,"text":"the harm we inflict on loved ones shows up as abuse and violence,","start":81586},{"end":91708,"text":"and relationship abuse is something that one in three women and one in four men will experience in their lifetime.","start":85183},{"end":95308,"text":"Now, if you're like most people, when you hear those stats,","start":92475},{"end":98142,"text":"you'll go, \"Oh, no, no, no, that would never happen to me.\"","start":95308},{"end":101600,"text":"It's instinctual to move away from the words \"abuse\" and \"violence,\"","start":98142},{"end":105475,"text":"to think that they happen to someone else somewhere else.","start":101600},{"end":109850,"text":"But the truth is, unhealthy relationships and abuse are all around us.","start":105475},{"end":112875,"text":"We just call them different things and ignore the connection.","start":109850},{"end":117292,"text":"Abuse sneaks up on us disguised in unhealthy love.","start":113892},{"end":125583,"text":"I work for an organization called One Love started by a family whose daughter Yeardley was killed by her ex-boyfriend.","start":119558},{"end":130986,"text":"This was a tragedy no one saw coming, but when they looked back,","start":126683},{"end":135892,"text":"they realized the warning signs were there just no one understood what they were seeing.","start":130986},{"end":139683,"text":"Called crazy or drama or too much drinking,","start":135892},{"end":142850,"text":"his actions weren't understood to be what they really were,","start":139683},{"end":145000,"text":"which was clear signs of danger.","start":142850},{"end":149600,"text":"Her family realized that if anyone had been educated about these signs,","start":145767},{"end":151500,"text":"her death could have been prevented.","start":149600},{"end":157743,"text":"So today we're on a mission to make sure that others have the information that Yeardley and her friends didn't.","start":152475},{"end":159517,"text":"We have three main goals:","start":157743},{"end":166225,"text":"give all of us a language for talking about a subject that's quite awkward and uncomfortable to discuss;","start":159517},{"end":171341,"text":"empower a whole front line, namely friends, to help; and,","start":166225},{"end":174333,"text":"in the process, improve all of our ability to love better.","start":171341},{"end":181767,"text":"To do this, it's always important to start by illuminating the unhealthy signs that we frequently miss,","start":175725},{"end":187225,"text":"and our work really focuses on creating content to start conversations with young people.","start":181767},{"end":189892,"text":"As you'd expect, most of our content is pretty serious,","start":187225},{"end":191767,"text":"given the subject at hand,","start":189892},{"end":196267,"text":"but today I'm going to use one of our more light-hearted yet still thought-provoking pieces,","start":191767},{"end":200375,"text":"\"The Couplets,\" to illuminate five markers of unhealthy love.","start":196267},{"end":204225,"text":"The first is intensity.","start":201225},{"end":206507,"text":"Blue: I haven't seen you in a couple days.","start":204225},{"end":207433,"text":"I've missed you.","start":206507},{"end":209410,"text":"Orange: I've missed you too.","start":207433},{"end":211365,"text":"Blue: I haven't seen you in five minutes.","start":209410},{"end":212600,"text":"It feels like a lifetime.","start":211365},{"end":215433,"text":"What have you been doing without me for five whole minutes?","start":212600},{"end":217892,"text":"Orange: It's been three minutes.","start":215433},{"end":219301,"text":"Anybody recognize that?","start":217892},{"end":220123,"text":"I don't know.","start":219301},{"end":220625,"text":"I do.","start":220123},{"end":224058,"text":"Abusive relationships don't start out abusive.","start":221850},{"end":226058,"text":"They start out exciting and exhilarating.","start":224058},{"end":229392,"text":"There's an intensity of affection and emotion, a rush.","start":226058},{"end":231100,"text":"It feels really good.","start":229392},{"end":233667,"text":"You feel so lucky, like you've hit the jackpot.","start":231100},{"end":235956,"text":"But in unhealthy love,","start":234600},{"end":242725,"text":"these feelings shift over time from exciting to overwhelming and maybe a little bit suffocating.","start":235956},{"end":244475,"text":"You feel it in your gut.","start":242725},{"end":251006,"text":"Maybe it's when your new boyfriend or girlfriend says \"I love you\" faster than you were ready for or starts showing up everywhere,","start":244475},{"end":252750,"text":"texting and calling a lot.","start":251006},{"end":256683,"text":"Maybe they're impatient when you're slow to respond,","start":253517},{"end":259708,"text":"even though they know you had other things going on that day.","start":256683},{"end":264267,"text":"It's important to remember that it's not how a relationship starts that matters,","start":260433},{"end":265808,"text":"it's how it evolves.","start":264267},{"end":270433,"text":"It's important in the early days of a new relationship to pay attention to how you're feeling.","start":265808},{"end":273058,"text":"Are you comfortable with the pace of intimacy?","start":270433},{"end":275792,"text":"Do you feel like you have space and room to breathe?","start":273058},{"end":282267,"text":"It's also really important to start practicing using your voice to talk about your own needs.","start":276642},{"end":284333,"text":"Are your requests respected?","start":282267},{"end":289142,"text":"A second marker is isolation.","start":285683},{"end":290892,"text":"Orange 2: Want to hang out?","start":289142},{"end":294225,"text":"Orange 1: Me and my boyfriend always have Monday Funday.","start":290892},{"end":295558,"text":"Orange 2: Want to hang out?","start":294225},{"end":298225,"text":"Orange 1: Me and my boyfriend always have Monday Funday.","start":295558},{"end":299149,"text":"Orange 2: Tomorrow?","start":298225},{"end":300975,"text":"Orange 1: It's our Tuesday Snooze Day.","start":299149},{"end":301943,"text":"Orange 2: Wednesday?","start":300975},{"end":303292,"text":"Orange 1: No Friends Day.","start":301943},{"end":305382,"text":"If you ask me,","start":304642},{"end":310100,"text":"isolation is one of the most frequently missed and misunderstood signs of unhealthy love.","start":305382},{"end":311392,"text":"Why?","start":310100},{"end":315933,"text":"Because every new relationship starts out with this intense desire to spend time together,","start":311392},{"end":318892,"text":"it's easy to miss when something shifts.","start":315933},{"end":324517,"text":"Isolation creeps in when your new boyfriend or girlfriend starts pulling you away from your friends and family,","start":318892},{"end":328250,"text":"your support system, and tethering you more tightly to them.","start":324517},{"end":332178,"text":"They might say things like, \"Why do you hang out with them?","start":329225},{"end":335973,"text":"They're such losers\" about your best friends, or, \"They want us to break up.","start":332178},{"end":339183,"text":"They're totally against us\" about your family.","start":335973},{"end":344833,"text":"Isolation is about sowing seeds of doubt about everyone from your prerelationship life.","start":339183},{"end":348058,"text":"Healthy love includes independence,","start":345975},{"end":354808,"text":"two people who love spending time together but who stay connected to the people and activities they cared about before.","start":348058},{"end":357725,"text":"While at first you might spend every waking minute together,","start":354808},{"end":360600,"text":"over time maintaining independence is key.","start":357725},{"end":366333,"text":"You do this by making plans with friends and sticking to them and encouraging your partner to do the same.","start":360600},{"end":370875,"text":"A third marker of unhealthy love is extreme jealousy.","start":367683},{"end":373725,"text":"Blue 2: What are you so happy about?","start":371600},{"end":376683,"text":"Blue 1: She just started following me on Instagram!","start":373725},{"end":378558,"text":"Blue 2: What are you so nervous about?","start":376683},{"end":382934,"text":"Blue 1: She, she just started following me, like, everywhere.","start":378558},{"end":390375,"text":"As the honeymoon period begins to fade, extreme jealousy can creep in.","start":386308},{"end":393183,"text":"Your partner might become more demanding,","start":391183},{"end":396183,"text":"needing to know where you are and who you're with all the time,","start":393183},{"end":399392,"text":"or they might start following you everywhere, online and off.","start":396183},{"end":403683,"text":"Extreme jealousy also brings with it possessiveness and mistrust,","start":399392},{"end":406975,"text":"frequent accusations of flirting with other people or cheating,","start":403683},{"end":412933,"text":"and refusal to listen to you when you tell them they have nothing to worry about and that you only love them.","start":406975},{"end":417892,"text":"Jealousy is a part of any human relationship, but extreme jealousy is different.","start":412933},{"end":420683,"text":"There's a threatening, desperate and angry edge to it.","start":417892},{"end":422958,"text":"Love shouldn't feel like this.","start":420683},{"end":426767,"text":"A fourth marker is belittling.","start":424183},{"end":428018,"text":"Blue: Wanna hang out?","start":426767},{"end":429350,"text":"Orange: I gotta study.","start":428018},{"end":432725,"text":"Blue: You'll get an A anyway, A for amazing.","start":429350},{"end":433915,"text":"Blue: Wanna hang out?","start":432725},{"end":435183,"text":"Orange: I gotta study.","start":433915},{"end":438642,"text":"Blue: You'll get an F anyway, F for, F for...","start":435183},{"end":439792,"text":"stupid.","start":438642},{"end":442308,"text":"Yeah, hmm.","start":440517},{"end":444892,"text":"In unhealthy love, words are used as weapons.","start":442308},{"end":449100,"text":"Conversations that used to be fun and lighthearted turn mean and embarrassing.","start":444892},{"end":452142,"text":"Maybe your partner makes fun of you in a way that hurts,","start":449100},{"end":455642,"text":"or maybe they tell stories and jokes for laughs at your expense.","start":452142},{"end":458392,"text":"When you try to explain that your feelings have been hurt,","start":455642},{"end":461808,"text":"they shut you down and accuse you of overreacting.","start":458392},{"end":463359,"text":"\"Why are you so sensitive?","start":461808},{"end":464566,"text":"What's your problem.","start":463359},{"end":466267,"text":"Give me a break.\"","start":464566},{"end":468375,"text":"You are silenced by these words.","start":466267},{"end":472683,"text":"It seems pretty obvious, but your partner should have your back.","start":469267},{"end":475350,"text":"Their words should build you up, not break you down.","start":472683},{"end":477767,"text":"They should keep your secrets and be loyal.","start":475350},{"end":481117,"text":"They should make you feel more confident, not less.","start":477767},{"end":485892,"text":"Finally, a fifth marker: volatility.","start":482100},{"end":488017,"text":"Orange 1: I'd be sad if we broke up.","start":485892},{"end":490000,"text":"Orange 2: I'd be sad too.","start":488017},{"end":493142,"text":"Orange 1: I'd so depressed if we ever broke up.","start":490892},{"end":494683,"text":"I'd throw myself off this step.","start":493142},{"end":497393,"text":"I would! Don't try to stop me!","start":494683},{"end":504767,"text":"Frequent breakups and makeups, high highs and low lows:","start":501017},{"end":507292,"text":"as tension rises, so does volatility.","start":504767},{"end":513558,"text":"Tearful, frustrated fights followed by emotional makeups, hateful and hurtful comments like,","start":508308},{"end":516225,"text":"\"You're worthless, I'm not even sure why I'm with you!\"","start":513558},{"end":521058,"text":"followed quickly by apologies and promises it will never happen again.","start":516225},{"end":529667,"text":"By this point, you've been so conditioned to this relationship roller coaster that you may not realize how unhealthy and maybe even dangerous your relationship has become.","start":521058},{"end":535850,"text":"It can be really hard to see when unhealthy love turns towards abuse,","start":531392},{"end":539767,"text":"but it's fair to say that the more of these markers your relationship might have,","start":535850},{"end":543267,"text":"the more unhealthy and maybe dangerous your relationship could be.","start":539767},{"end":545475,"text":"And if your instinct is to break up and leave,","start":543267},{"end":549642,"text":"which is advice so many of us give our friends when they're in unhealthy relationships,","start":545475},{"end":551600,"text":"that's not always the best advice.","start":549642},{"end":554225,"text":"Time of breakup can be a real trigger for violence.","start":551600},{"end":557517,"text":"If you fear you might be headed towards abuse or in abuse,","start":554225},{"end":561708,"text":"you need to consult with experts to get the advice on how to leave safely.","start":557517},{"end":567517,"text":"But it's not just about romantic relationships and it's not just about violence.","start":562892},{"end":573708,"text":"Understanding the signs of unhealthy love can help you audit and understand nearly every relationship in your life.","start":567517},{"end":575426,"text":"For the first time,","start":574475},{"end":584392,"text":"you might understand why you're disappointed in a friendship or why every interaction with a certain family member leaves you discouraged and anxious.","start":575426},{"end":589833,"text":"You might even begin to see how your own intensity and jealousy is causing problems with colleagues at work.","start":584392},{"end":594350,"text":"Understanding is the first step to improving,","start":591058},{"end":599558,"text":"and while you can't make every unhealthy relationship healthy -- some you're going to have to leave behind --","start":594350},{"end":604100,"text":"you can do your part every day to do relationships better.","start":599558},{"end":608100,"text":"And here's the exciting news: it's actually not rocket science.","start":604100},{"end":615667,"text":"Open communication, mutual respect, kindness, patience -- we can practice these things every day.","start":608100},{"end":619475,"text":"And while practice will definitely make you better,","start":616725},{"end":623267,"text":"I have to promise you it's also not going to make you perfect.","start":619475},{"end":627475,"text":"I do this for a living and every day I think and talk about healthy relationships,","start":623267},{"end":630100,"text":"and still I do unhealthy things.","start":627475},{"end":634429,"text":"Just the other day as I was trying to shuttle my four kids out the door amidst quarreling,","start":630100},{"end":638642,"text":"squabbling and complaints about breakfast, I completely lost it.","start":634429},{"end":642142,"text":"With an intentionally angry edge, I screamed,","start":638642},{"end":644433,"text":"\"Everybody just shut up and do what I say!","start":642142},{"end":646017,"text":"You are the worst!","start":644433},{"end":651601,"text":"I am going to take away screen time and dessert and anything else you could possibly ever enjoy in life!\"","start":646017},{"end":654434,"text":"Anybody been there?","start":652975},{"end":659075,"text":"Volatility, belittling.","start":657725},{"end":663677,"text":"My oldest son turned around and looked at me,","start":661267},{"end":665976,"text":"and said, \"Mom, that's not love.\"","start":663677},{"end":672142,"text":"For a minute, I really wanted to kill him for calling me out.","start":669225},{"end":673683,"text":"Trust me.","start":672142},{"end":678308,"text":"But then I gathered myself and I thought, you know what, I'm actually proud.","start":673683},{"end":682361,"text":"I'm proud that he has a language to make me pause.","start":678308},{"end":686558,"text":"I want all of my kids to understand what the bar should be for how they're treated","start":682361},{"end":691792,"text":"and to have a language and a voice to use when that bar is not met versus just accepting it.","start":686558},{"end":698392,"text":"For too long, we've treated relationships as a soft topic,","start":693517},{"end":703558,"text":"when relationship skills are one of the most important and hard to build things in life.","start":698392},{"end":709767,"text":"Not only can understanding unhealthy signs help you avoid the rabbit hole that leads to unhealthy love,","start":703558},{"end":715542,"text":"but understanding and practicing the art of being healthy can improve nearly every aspect of your life.","start":709767},{"end":721225,"text":"I'm completely convinced that while love is an instinct and an emotion,","start":716475},{"end":726433,"text":"the ability to love better is a skill we can all build and improve on over time.","start":721225},{"end":727783,"text":"Thank you.","start":726433}],"channel_name":"TED","date_created":"2026-11-16T03:04:53.064+00:00","date_updated":null,"yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi_webp/ON4iy8hq2hM/sddefault.webp","transcript_kind":"manual","transcript_lang":"en","youtube_video_id":"ON4iy8hq2hM","transcript_updated_at":"2026-11-16T03:04:53.062+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = 'ON4iy8hq2hM') on conflict do nothing;
