  insert into video_tags select (jsonb_populate_record(null::video_tags, $row${"wpm":177.4,"note":null,"ai_at":"2026-11-16T04:10:21.691684+00:00","level":6,"score":5.72,"topic":null,"broken":false,"ai_error":null,"ai_topic":"relationships","ai_reason":"Claude gắn theo tiêu đề","level_why":"nói nhanh (177 từ/phút)","subtopics":null,"duration_s":715,"rare_ratio":0.066,"signals_at":"2026-11-16T03:44:33.417+00:00","word_count":1936,"editor_pick":false,"known_ratio":0.934,"noise_ratio":0,"ai_subtopics":[],"content_type":null,"date_updated":"2026-11-16T03:44:33.417+00:00","level_manual":null,"speech_ratio":0.916,"ai_confidence":"medium","avg_cue_words":10,"speaker_turns":0,"ai_content_type":null,"source_video_id":"1b0dae7c-8011-416b-9ae9-c44896c9e3cf"}$row$::jsonb || jsonb_build_object('source_video_id', v))).* on conflict do nothing;
  insert into il_lessons select (jsonb_populate_record(null::il_lessons, $row${"id":"d15579dc-1aca-4883-a327-b1e083d437e1","note":null,"slug":"when-love-feels-too-intense","sort":0,"focus":"linking","intro":"Cảm giác \"như trúng số\" lúc mới yêu có phải lúc nào cũng là dấu hiệu tốt?","level":2,"title":"Tình yêu quá mãnh liệt có đáng lo không?","topic":null,"end_ms":284333,"status":"draft","explore":"## Bài nói\r\nKatie Hood làm việc tại tổ chức One Love, nơi giúp người trẻ nhận ra các dấu hiệu của một mối quan hệ không lành mạnh. Trong bài TED này, cô cho rằng ai cũng có lúc làm điều chưa tốt với người mình thương, và điều quan trọng là biết nhận ra để sửa.\r\n\r\n## Dấu hiệu đầu tiên: quá mãnh liệt\r\nMối quan hệ độc hại thường không xấu ngay từ đầu. Nó bắt đầu bằng sự hào hứng, rồi dần chuyển sang choáng ngợp và ngột ngạt, ví dụ khi người kia liên tục xuất hiện, nhắn tin, gọi điện và khó chịu khi bạn trả lời chậm. Cô khuyên rằng điều đáng xem không phải mối quan hệ bắt đầu ngọt ngào ra sao, mà là về sau nó thay đổi theo hướng nào.\r\n\r\n## Tự hỏi mình\r\n- Mình có thoải mái với tốc độ gần gũi này không?\r\n- Mình có còn không gian riêng không?\r\n- Khi mình nói ra điều mình cần, người kia có tôn trọng không?","short_id":"42ff61a0","start_ms":221850,"is_premium":false,"gist_answer":2,"gist_prompt":"Khi mới bắt đầu một mối quan hệ, người nói khuyên điều gì?","date_created":"2026-11-25T11:36:09.139817+00:00","date_updated":"2026-11-25T11:36:09.823151+00:00","gist_explain":"Người nói khuyên chú ý cảm giác của mình và tập nói về nhu cầu của bản thân.","gist_options":["Càng mãnh liệt thì càng chắc đó là tình yêu tốt","Đừng đòi hỏi gì để người kia luôn thấy vui","Để ý cảm xúc của mình và nói ra điều mình cần"],"gist_sentences":[8,11],"source_video_id":"1b0dae7c-8011-416b-9ae9-c44896c9e3cf"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
  insert into il_sentences ("n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id") select "n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id" from jsonb_populate_recordset(null::il_sentences, $row$[{"n":1,"id":"7836eed7-c847-426d-9a6a-8a3e0da81c07","sub":"Những mối quan hệ bạo hành không bắt đầu bằng bạo hành.","part":1,"text":"Abusive relationships don't start out abusive.","traps":[{"kind":"linking","note":"Âm t giữa hai nguyên âm đọc nhẹ thành đ, hai từ dính liền.","real":"/ˈstɑːr ɾaʊt/ (nghe như \"star-ĐAO(t)\")","text":"start out","skill":"flap-t"}],"end_ms":224058,"start_ms":221850,"key_words":["dont"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":2,"id":"4e27b715-fc93-4a7c-97c6-7df033922d00","sub":"Chúng bắt đầu đầy hào hứng và phấn khích.","part":1,"text":"They start out exciting and exhilarating.","traps":[{"kind":"linking","note":"and đọc yếu rồi nối âm n vào exhilarating.","real":"/ən ɪɡˈzɪl/ (nghe như \"ơ-nig-ZIL\")","text":"and exhilarating","skill":"linking-words"}],"end_ms":226058,"start_ms":224058,"key_words":[],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":3,"id":"ed3eca49-8136-4a24-9998-3f594d9a8059","sub":"Có sự mãnh liệt của tình cảm và cảm xúc, một cơn lâng lâng.","part":1,"text":"There's an intensity of affection and emotion, a rush.","traps":[{"kind":"linking","note":"Âm z của There's nối sang an.","real":"/ðer zən/ (nghe như \"đe-zơn\")","text":"There's an","skill":"linking-words"}],"end_ms":229392,"start_ms":226058,"key_words":["intensity"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":4,"id":"e843f306-ba7b-44ca-8483-c1636e6f0d21","sub":"Cảm giác rất tuyệt.","part":1,"text":"It feels really good.","traps":[],"end_ms":231100,"start_ms":229392,"key_words":[],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":5,"id":"b57a36f8-7846-4a62-9d17-fa3a4f07d861","sub":"Bạn thấy mình thật may mắn, như trúng số độc đắc.","part":1,"text":"You feel so lucky, like you've hit the jackpot.","traps":[],"end_ms":233667,"start_ms":231100,"key_words":["lucky"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":6,"id":"a9e80acf-acfb-46e9-8df5-b3b2b2147fa6","sub":"Bạn cảm thấy điều đó từ trong bụng.","part":1,"text":"You feel it in your gut.","traps":[{"kind":"linking","note":"Ba từ ngắn nối thành một chuỗi liền.","real":"/ˈfiː lɪ ɾɪn/ (nghe như \"FIU-li-đin\")","text":"feel it in","skill":"linking-words"}],"end_ms":244475,"start_ms":242725,"key_words":["gut"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":7,"id":"c6781404-8b5f-4081-8d2a-72b2cffb41c7","sub":"Điều quan trọng cần nhớ là: một mối quan hệ bắt đầu thế nào không quan trọng bằng nó phát triển ra sao.","part":1,"text":"It's important to remember that it's not how a relationship starts that matters, it's how it evolves.","traps":[],"end_ms":265808,"start_ms":260433,"key_words":["not","evolves"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":8,"id":"3861c54a-34e9-4898-8cdb-d508f16a29e6","sub":"Những ngày đầu của một mối quan hệ mới, việc để ý cảm giác của mình rất quan trọng.","part":1,"text":"It's important in the early days of a new relationship to pay attention to how you're feeling.","traps":[],"end_ms":270433,"start_ms":265808,"key_words":["feeling"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":9,"id":"190e9063-22e6-45a2-8106-80b739d799b9","sub":"Bạn có thoải mái với tốc độ gần gũi này không?","part":1,"text":"Are you comfortable with the pace of intimacy?","traps":[{"kind":"linking","note":"Âm s của pace nối sang of đọc yếu.","real":"/ˈpeɪ səv/ (nghe như \"PÂY-sơv\")","text":"pace of","skill":"linking-words"}],"end_ms":273058,"start_ms":270433,"key_words":["pace"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":10,"id":"972f8b47-3d29-4cb9-98f2-e4b213f0b262","sub":"Bạn có thấy mình còn không gian để thở không?","part":1,"text":"Do you feel like you have space and room to breathe?","traps":[],"end_ms":275792,"start_ms":273058,"key_words":["breathe"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":11,"id":"cee75107-3542-4479-8369-2eb3b6c3bb39","sub":"Cũng rất quan trọng là bắt đầu tập dùng tiếng nói của mình để nói về điều mình cần.","part":1,"text":"It's also really important to start practicing using your voice to talk about your own needs.","traps":[{"kind":"linking","note":"Âm k của talk nối sang about.","real":"/ˈtɔː kəˌbaʊt/ (nghe như \"TO-kơ-BAO(t)\")","text":"talk about","skill":"linking-words"}],"end_ms":282267,"start_ms":276642,"key_words":["needs"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":12,"id":"e3900f92-d41d-454c-a431-5f8f4dedf526","sub":"Những đề nghị của bạn có được tôn trọng không?","part":1,"text":"Are your requests respected?","traps":[{"kind":"imagine","note":"Âm t kẹt giữa hai âm s nên gần mất, khó nghe đuôi số nhiều.","real":"/rɪˈkwes(t)s/ (nghe như \"ri-KWES\")","text":"requests","skill":"t-d-dropping"}],"end_ms":284333,"start_ms":282267,"key_words":["respected"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"}]$row$::jsonb) on conflict do nothing;
  insert into il_translations ("key", "lang", "text", "lesson_id") select "key", "lang", "text", "lesson_id" from jsonb_populate_recordset(null::il_translations, $row$[{"key":"title","lang":"en-US","text":"Is love that feels too intense a warning sign?","lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"key":"intro","lang":"en-US","text":"Is that \"hit the jackpot\" feeling at the start always a good sign?","lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"key":"explore","lang":"en-US","text":"## The talk\r\nKatie Hood works at One Love, an organisation that helps young people spot the signs of an unhealthy relationship. In this TED talk she says everyone sometimes treats loved ones badly, and what matters is noticing it and doing better.\r\n\r\n## The first marker: intensity\r\nAbusive relationships rarely start badly. They start with excitement and slowly become overwhelming and suffocating.\r\n\r\n## Ask yourself\r\n- Am I comfortable with the pace?\r\n- Do I still have room to breathe?\r\n- Are my requests respected?","lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"}]$row$::jsonb) on conflict do nothing;
end $do$;

-- il_lessons bfd37ff0-5b16-4600-81ce-3fada909932d: Sự tự tin có rèn được như cơ bắp không?
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"abe26327-5afe-42c5-8b27-cfda9d49d2b8","title":"3 tips to boost your confidence - TED-Ed","status":"published","transcript":[{"end":2495,"text":"Translator: Jennifer Cody Reviewer:","start":0},{"end":11186,"text":"Jessica Ruby When faced with a big challenge where potential failure seems to lurk at every corner,","start":2495},{"end":16269,"text":"maybe you've heard this advice before: \"Be more confident.\"","start":11186},{"end":19380,"text":"And most likely, this is what you think when you hear it:","start":16269},{"end":22111,"text":"\"If only it were that simple.\"","start":19380},{"end":24172,"text":"But what is confidence?","start":22111},{"end":29986,"text":"Take the belief that you are valuable, worthwhile, and capable, also known as self-esteem,","start":24172},{"end":34619,"text":"add in the optimism that comes when you are certain of your abilities,","start":29986},{"end":40719,"text":"and then empowered by these, act courageously to face a challenge head-on.","start":34619},{"end":42707,"text":"This is confidence.","start":40719},{"end":46534,"text":"It turns thoughts into action.","start":42707},{"end":49330,"text":"So where does confidence even come from?","start":46534},{"end":52482,"text":"There are several factors that impact confidence.","start":49330},{"end":55342,"text":"One: what you're born with, such as your genes,","start":52482},{"end":60316,"text":"which will impact things like the balance of neurochemicals in your brain.","start":55342},{"end":62887,"text":"Two: how you're treated.","start":60316},{"end":66204,"text":"This includes the social pressures of your environment.","start":62887},{"end":70888,"text":"And three: the part you have control over, the choices you make,","start":66204},{"end":72366,"text":"the risks you take,","start":70888},{"end":76503,"text":"and how you think about and respond to challenges and setbacks.","start":72366},{"end":80235,"text":"It isn't possible to completely untangle these three factors,","start":76503},{"end":85889,"text":"but the personal choices we make certainly play a major role in confidence development.","start":80235},{"end":89423,"text":"So, by keeping in mind a few practical tips,","start":85889},{"end":95269,"text":"we do actually have the power to cultivate our own confidence.","start":89423},{"end":97873,"text":"Tip 1: a quick fix.","start":95269},{"end":102858,"text":"There are a few tricks that can give you an immediate confidence boost in the short term.","start":97873},{"end":106617,"text":"Picture your success when you're beginning a difficult task,","start":102858},{"end":109573,"text":"something as simple as listening to music with deep bass;","start":106617},{"end":113396,"text":"it can promote feelings of power.","start":109573},{"end":118404,"text":"You can even strike a powerful pose or give yourself a pep talk.","start":113396},{"end":123674,"text":"Tip two: believe in your ability to improve.","start":118404},{"end":125863,"text":"If you're looking for a long-term change,","start":123674},{"end":129745,"text":"consider the way you think about your abilities and talents.","start":125863},{"end":132093,"text":"Do you think they are fixed at birth,","start":129745},{"end":134950,"text":"or that they can be developed, like a muscle?","start":132093},{"end":140444,"text":"These beliefs matter because they can influence how you act when you're faced with setbacks.","start":134950},{"end":142113,"text":"If you have a fixed mindset,","start":140444},{"end":144731,"text":"meaning that you think your talents are locked in place,","start":142113},{"end":150066,"text":"you might give up, assuming you've discovered something you're not very good at.","start":144731},{"end":154502,"text":"But if you have a growth mindset and think your abilities can improve,","start":150066},{"end":158193,"text":"a challenge is an opportunity to learn and grow.","start":154502},{"end":160671,"text":"Neuroscience supports the growth mindset.","start":158193},{"end":165878,"text":"The connections in your brain do get stronger and grow with study and practice.","start":160671},{"end":168059,"text":"It also turns out, on average,","start":165878},{"end":171172,"text":"people who have a growth mindset are more successful,","start":168059},{"end":176379,"text":"getting better grades, and doing better in the face of challenges.","start":171172},{"end":179601,"text":"Tip three: practice failure.","start":176379},{"end":182256,"text":"Face it, you're going to fail sometimes.","start":179601},{"end":183606,"text":"Everyone does.","start":182256},{"end":189648,"text":"J.K. Rowling was rejected by twelve different publishers before one picked up \"Harry Potter.\"","start":184412},{"end":193086,"text":"The Wright Brothers built on history's failed attempts at flight,","start":189648},{"end":197485,"text":"including some of their own, before designing a successful airplane.","start":193086},{"end":208026,"text":"Studies show that those who fail regularly and keep trying anyway are better equipped to respond to challenges and setbacks in a constructive way.","start":197485},{"end":214073,"text":"They learn how to try different strategies, ask others for advice, and perservere.","start":208026},{"end":216867,"text":"So, think of a challenge you want to take on,","start":214073},{"end":219599,"text":"realize it's not going to be easy,","start":216867},{"end":224191,"text":"accept that you'll make mistakes, and be kind to yourself when you do.","start":219599},{"end":229361,"text":"Give yourself a pep talk, stand up, and go for it.","start":224191},{"end":232737,"text":"The excitement you'll feel knowing that whatever the result,","start":229361},{"end":236073,"text":"you'll have gained greater knowledge and understanding.","start":232737},{"end":238023,"text":"This is confidence.","start":236073}],"channel_name":"TED-Ed","date_created":"2026-11-16T03:07:54.967+00:00","date_updated":null,"yarn_clip_id":null,"thumbnail_url":"https://i.ytimg.com/vi_webp/l_NYrWqUR40/sddefault.webp","transcript_kind":"manual","transcript_lang":"en","youtube_video_id":"l_NYrWqUR40","transcript_updated_at":"2026-11-16T03:07:54.966+00:00"}$row$::jsonb) where not exists (select 1 from source_videos where youtube_video_id = 'l_NYrWqUR40') on conflict do nothing;
