  insert into video_tags select (jsonb_populate_record(null::video_tags, $row${"wpm":147.7,"note":null,"ai_at":"2026-11-16T04:10:21.691684+00:00","level":2,"score":3.92,"topic":null,"broken":false,"ai_error":null,"ai_topic":"self_improvement","ai_reason":"Claude gắn theo tiêu đề","level_why":"không có tín hiệu nổi bật","subtopics":null,"duration_s":238,"rare_ratio":0.05,"signals_at":"2026-11-16T03:44:34.53+00:00","word_count":576,"editor_pick":false,"known_ratio":0.95,"noise_ratio":0,"ai_subtopics":[],"content_type":null,"date_updated":"2026-11-16T03:44:34.53+00:00","level_manual":null,"speech_ratio":0.983,"ai_confidence":"medium","avg_cue_words":9.4,"speaker_turns":0,"ai_content_type":null,"source_video_id":"abe26327-5afe-42c5-8b27-cfda9d49d2b8"}$row$::jsonb || jsonb_build_object('source_video_id', v))).* on conflict do nothing;
  insert into il_lessons select (jsonb_populate_record(null::il_lessons, $row${"id":"bfd37ff0-5b16-4600-81ce-3fada909932d","note":null,"slug":"can-confidence-be-trained","sort":0,"focus":"linking","intro":"Có người tin tài năng là trời cho, có người tin nó lớn lên được. Niềm tin đó thay đổi nhiều hơn bạn nghĩ.","level":1,"title":"Sự tự tin có rèn được như cơ bắp không?","topic":null,"end_ms":183606,"status":"draft","explore":"## Tự tin từ đâu ra\r\nVideo của TED-Ed cho rằng sự tự tin đến từ ba nguồn: thứ bạn sinh ra đã có, cách người khác đối xử với bạn, và những lựa chọn của chính bạn. Phần cuối cùng là phần bạn điều khiển được.\r\n\r\n## Ba mẹo\r\n- Cách nhanh: hình dung mình thành công, nghe nhạc, đứng ở tư thế mạnh mẽ, tự động viên.\r\n- Tin rằng mình tiến bộ được.\r\n- Tập thất bại: ai cũng có lúc sai.\r\n\r\n## Hai kiểu tư duy\r\nNgười có tư duy cố định nghĩ tài năng không đổi, nên dễ bỏ cuộc. Người có tư duy phát triển coi thử thách là dịp để học. Video cũng nhắc J.K. Rowling từng bị nhiều nhà xuất bản từ chối trước khi Harry Potter được nhận. Theo video, não bộ thật sự thay đổi khi ta học và luyện tập, nên mỗi lần làm sai cũng là một bước giúp ta quen với khó khăn.","short_id":"b516947f","start_ms":113396,"is_premium":false,"gist_answer":2,"gist_prompt":"Vì sao cách bạn nghĩ về khả năng của mình lại quan trọng?","date_created":"2026-11-25T11:36:10.753418+00:00","date_updated":"2026-11-25T11:36:11.399982+00:00","gist_explain":"Người nói bảo niềm tin này ảnh hưởng đến cách bạn hành động khi gặp trở ngại.","gist_options":["Vì khả năng đã cố định từ lúc bạn mới sinh ra","Vì nghĩ tích cực thì bạn sẽ không bao giờ thất bại","Vì nó ảnh hưởng đến cách bạn phản ứng khi gặp trở ngại"],"gist_sentences":[5],"source_video_id":"abe26327-5afe-42c5-8b27-cfda9d49d2b8"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
  insert into il_sentences ("n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id") select "n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id" from jsonb_populate_recordset(null::il_sentences, $row$[{"n":1,"id":"07a990aa-9717-4eeb-a7fb-db88129f19a7","sub":"Bạn thậm chí có thể đứng ở một tư thế đầy sức mạnh hoặc tự nói lời động viên.","part":1,"text":"You can even strike a powerful pose or give yourself a pep talk.","traps":[{"kind":"linking","note":"Âm f cuối yourself nối sang a.","real":"/jərˈsel fə/ (nghe như \"jơ-SEL-fơ\")","text":"yourself a","skill":"linking-words"}],"end_ms":118404,"start_ms":113396,"key_words":["pose"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":2,"id":"ffeea033-398c-40ec-9d3a-70455ecbba4a","sub":"Mẹo thứ hai: tin vào khả năng tiến bộ của mình.","part":1,"text":"Tip two: believe in your ability to improve.","traps":[{"kind":"linking","note":"Âm v của believe nối sang in.","real":"/bɪˈliː vɪn/ (nghe như \"bơ-LI-vin\")","text":"believe in","skill":"linking-words"}],"end_ms":123674,"start_ms":118404,"key_words":["improve"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":3,"id":"a2223d4a-2ada-4161-bb28-3ca72bfa1611","sub":"Nếu bạn muốn thay đổi lâu dài, hãy xem lại cách mình nghĩ về năng lực và tài năng của bản thân.","part":1,"text":"If you're looking for a long-term change, consider the way you think about your abilities and talents.","traps":[{"kind":"linking","note":"Âm k của think nối sang about.","real":"/ˈθɪŋ kəˌbaʊt/ (nghe như \"THING-kơ-BAO(t)\")","text":"think about","skill":"linking-words"}],"end_ms":129745,"start_ms":123674,"key_words":[],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":4,"id":"d77bed81-ff5c-4cba-871f-2429067a1c25","sub":"Bạn nghĩ chúng cố định từ khi sinh ra, hay có thể rèn được, giống như cơ bắp?","part":1,"text":"Do you think they are fixed at birth, or that they can be developed, like a muscle?","traps":[{"kind":"linking","note":"Đuôi t của fixed nối sang at, dễ sót quá khứ phân từ.","real":"/ˈfɪk stət/ (nghe như \"FIK-stơt\")","text":"fixed at","skill":"linking-words"}],"end_ms":134950,"start_ms":129745,"key_words":["fixed","developed"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":5,"id":"143d56ae-625b-4866-a4e6-88ceb015babb","sub":"Những niềm tin này quan trọng vì chúng ảnh hưởng đến cách bạn hành động khi gặp trở ngại.","part":1,"text":"These beliefs matter because they can influence how you act when you're faced with setbacks.","traps":[{"kind":"linking","note":"Đuôi ed đứng trước w gần như mất.","real":"/ˈfeɪs(t) wɪð/ (nghe như \"FÂYS-with\")","text":"faced with","skill":"ed-endings"}],"end_ms":140444,"start_ms":134950,"key_words":["influence"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":6,"id":"0044b3c3-7f77-416b-99d2-3d1365d6d90e","sub":"Khoa học thần kinh ủng hộ tư duy phát triển.","part":1,"text":"Neuroscience supports the growth mindset.","traps":[],"end_ms":160671,"start_ms":158193,"key_words":["supports"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":7,"id":"fbd215ba-7002-48ee-b829-b408cd46d50b","sub":"Các kết nối trong não bạn thật sự mạnh lên và phát triển khi học và luyện tập.","part":1,"text":"The connections in your brain do get stronger and grow with study and practice.","traps":[],"end_ms":165878,"start_ms":160671,"key_words":["stronger"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":8,"id":"58b9554c-b684-432a-8d2b-1f75723d9a88","sub":"Mẹo thứ ba: tập thất bại.","part":1,"text":"Tip three: practice failure.","traps":[],"end_ms":179601,"start_ms":176379,"key_words":["failure"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":9,"id":"12f2926d-bafa-4b7e-a36d-87d52b9befb1","sub":"Chấp nhận đi, thỉnh thoảng bạn sẽ thất bại.","part":1,"text":"Face it, you're going to fail sometimes.","traps":[{"kind":"linking","note":"Âm s của Face nối sang it thành một tiếng liền.","real":"/ˈfeɪ sɪt/ (nghe như \"FÂY-sit\")","text":"Face it","skill":"linking-words"}],"end_ms":182256,"start_ms":179601,"key_words":["fail"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":10,"id":"92050805-13a8-401d-91c2-3d59bc3d99cf","sub":"Ai cũng vậy.","part":1,"text":"Everyone does.","traps":[],"end_ms":183606,"start_ms":182256,"key_words":["everyone"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"}]$row$::jsonb) on conflict do nothing;
  insert into il_translations ("key", "lang", "text", "lesson_id") select "key", "lang", "text", "lesson_id" from jsonb_populate_recordset(null::il_translations, $row$[{"key":"title","lang":"en-US","text":"Can confidence be trained like a muscle?","lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"key":"intro","lang":"en-US","text":"Some think talent is fixed, others think it grows. That belief changes more than you expect.","lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"key":"explore","lang":"en-US","text":"## Where confidence comes from\r\nThis TED-Ed video names three sources: what you are born with, how others treat you, and your own choices. The last one is yours to control.\r\n\r\n## Three tips\r\n- A quick fix: picture success, strike a powerful pose, give yourself a pep talk.\r\n- Believe you can improve.\r\n- Practise failing.\r\n\r\n## Two mindsets\r\nA fixed mindset treats talent as locked in. A growth mindset treats a challenge as a chance to learn.","lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"}]$row$::jsonb) on conflict do nothing;
end $do$;

-- il_lessons aae8d08c-786d-4f39-9ebf-7d37993a2f5b: Tiếng gầm trong Roar của Katy Perry từ đâu ra?
insert into source_videos select * from jsonb_populate_record(null::source_videos, $row${"id":"39c4f5c6-dc35-4b25-89c7-92d4cd364eaa","title":"Katy Perry - Roar ( Slowed + Reverb )","status":"published","transcript":[{"end":9770,"text":"I used to bite my tongue and hold my breath","start":6650},{"end":12870,"text":"Scared to rock the boat and make a mess","start":10220},{"end":18550,"text":"So I sat quietly, agreed politely","start":12870},{"end":22100,"text":"I guess that I forgot I had a choice","start":19000},{"end":25210,"text":"I let you push me past the breaking point","start":22100},{"end":30760,"text":"I stood for nothing, so I fell for everything","start":25210},{"end":33770,"text":"You held me down, but I got up","start":30760},{"end":36900,"text":"Already brushing off the dust","start":34880},{"end":40060,"text":"You hear my voice, you hear that sound","start":36900},{"end":43140,"text":"Like thunder gonna shake the ground","start":40460},{"end":46250,"text":"You held me down, but I got up","start":43140},{"end":49110,"text":"Get ready 'cause I've had enough","start":46250},{"end":52590,"text":"I see it all, I see it now","start":49110},{"end":60900,"text":"I got the eye of the lion, a fighter, dancing through the fire","start":53070},{"end":68980,"text":"'Cause I am a champion and you're gonna hear me roar","start":60890},{"end":73190,"text":"Louder, louder than a lion","start":68720},{"end":81090,"text":"'Cause I am a champion and you're gonna hear me roar","start":73190},{"end":83270,"text":"Oh oh oh oh oh oh","start":81850},{"end":86180,"text":"Oh oh oh oh oh oh","start":83790},{"end":93120,"text":"You're gonna hear me roar","start":89400},{"end":98830,"text":"Now I'm floating like a butterfly","start":95830},{"end":101630,"text":"Stinging like a bee I earned my stripes","start":98830},{"end":107210,"text":"I went from zero, to my own hero","start":101630},{"end":110450,"text":"You held me down, but I got up","start":107210},{"end":113550,"text":"Alrea