  insert into video_tags select (jsonb_populate_record(null::video_tags, $row${"wpm":114.7,"note":null,"ai_at":"2026-11-23T05:49:42.661+00:00","level":2,"score":3.26,"topic":null,"broken":false,"ai_error":null,"ai_topic":"arts_literature","ai_reason":"Video là bản nhạc \"Roar\" của Katy Perry được làm chậm và thêm reverb, kèm lời bài hát.","level_why":"nói chậm (115 từ/phút); Gameshow / chương trình giải trí: sub không ghi ai nói, khó hơn số liệu","subtopics":null,"duration_s":239,"rare_ratio":0.067,"signals_at":"2026-11-23T05:49:34.637+00:00","word_count":390,"editor_pick":false,"known_ratio":0.933,"noise_ratio":0,"ai_subtopics":["entertainment_celebrity"],"content_type":null,"date_updated":"2026-11-23T05:49:34.637+00:00","level_manual":null,"speech_ratio":0.853,"ai_confidence":"low","avg_cue_words":7.5,"speaker_turns":0,"ai_content_type":"show","source_video_id":"39c4f5c6-dc35-4b25-89c7-92d4cd364eaa"}$row$::jsonb || jsonb_build_object('source_video_id', v))).* on conflict do nothing;
  insert into il_lessons select (jsonb_populate_record(null::il_lessons, $row${"id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b","note":"Bài hát bản chậm có vang: nghe lại giờ câu và cách đọc từng bẫy trước khi duyệt. Chưa có phụ đề tiếng Việt.","slug":"katy-perry-roar","sort":0,"focus":"linking","intro":"Roar của Katy Perry bản chậm, nghe rõ từng chữ hơn hẳn. Thử xem bạn bắt được bao nhiêu chỗ chữ này dính vào chữ kia.","level":1,"title":"Tiếng gầm trong Roar của Katy Perry từ đâu ra?","topic":null,"end_ms":73190,"status":"draft","explore":"## Một bài hát về chuyện lên tiếng\r\nRoar mở đầu bằng một người quen cắn răng chịu. Sợ làm căng, sợ sinh chuyện, nên người ta nói gì cũng gật cho qua. Nhịn mãi thì quên luôn là mình cũng được quyền chọn.\r\n## Tới lúc chịu hết nổi\r\nBị đẩy quá giới hạn, người đó ngã rồi lại đứng dậy, phủi bụi và cất tiếng. Bài hát dùng hình ảnh sấm rền làm rung mặt đất để tả tiếng nói ấy lớn cỡ nào.\r\n## Mắt hổ, tiếng sư tử\r\n- \"Mắt hổ\" là cách người Mỹ nói về ánh mắt quyết thắng, nổi tiếng từ một bài hát gắn với phim võ sĩ Rocky.\r\n- Tiếng gầm là lời tuyên bố: giờ thì ai cũng phải nghe mình nói.\r\n## Đoạn sau của video\r\nKaty còn nhắc con bướm và con ong, gợi tới câu nói của võ sĩ quyền Anh Muhammad Ali, rồi kể chuyện đi lên từ con số không và tự làm người hùng của đời mình.","short_id":"0217c8ad","start_ms":6650,"is_premium":false,"gist_answer":0,"gist_prompt":"Trong đoạn này, Katy khác đi ra sao?","date_created":"2026-11-26T07:30:56.602857+00:00","date_updated":"2026-11-26T07:30:57.404804+00:00","gist_explain":"Đầu đoạn Katy im lặng gật đầu cho qua, sau đó đứng dậy và nói to lên.","gist_options":["Hết nhịn nhục, dám nói cho ra lẽ","Hết hay cãi, giờ im cho yên chuyện","Hết lủi thủi một mình, đã có người mới"],"gist_sentences":[3,7,14],"source_video_id":"39c4f5c6-dc35-4b25-89c7-92d4cd364eaa"}$row$::jsonb || jsonb_build_object('source_video_id', v))).*;
  insert into il_sentences ("n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id") select "n", "id", "sub", "part", "text", "traps", "end_ms", "start_ms", "key_words", "lesson_id" from jsonb_populate_recordset(null::il_sentences, $row$[{"n":1,"id":"2356f51c-9054-496b-aeea-06e841c8ea5a","sub":null,"part":1,"text":"I used to bite my tongue and hold my breath","traps":[{"kind":"linking","note":"d trong used mất, dính luôn vào to nên chỉ còn nghe \"yoos-tơ\".","real":"/ˈjuːs tə/ (nghe như \"DIÚS-tơ\")","text":"used to","skill":"t-d-dropping"}],"end_ms":9770,"start_ms":6650,"key_words":["bite","breath"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":2,"id":"bd7e3f28-d2fb-460a-ba1f-ffc462156c97","sub":null,"part":1,"text":"Scared to rock the boat and make a mess","traps":[{"kind":"linking","note":"k cuối của make chạy sang a, nghe như một chữ.","real":"/ˈmeɪ kə/ (nghe như \"MÂY-kơ\")","text":"make a","skill":"linking-words"}],"end_ms":12870,"start_ms":10220,"key_words":["scared"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":3,"id":"0173c4ff-5d61-4f15-9c8f-e6fce39a6752","sub":null,"part":1,"text":"So I sat quietly, agreed politely","traps":[],"end_ms":18550,"start_ms":12870,"key_words":["quietly","agreed"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":4,"id":"07beb36d-f26d-45f6-aada-e668bc316bed","sub":null,"part":1,"text":"I guess that I forgot I had a choice","traps":[{"kind":"linking","note":"t giữa hai nguyên âm đọc nhẹ như \"đ\", dính vào I.","real":"/fərˈɡɑː ɾaɪ/ (nghe như \"fơ-GA-đai\")","text":"forgot I","skill":"flap-t"},{"kind":"linking","note":"d của had nối sang a, nghe như một chữ \"he-đơ\".","real":"/ˈhæ ɾə/ (nghe như \"HE-đơ\")","text":"had a","skill":"linking-words"}],"end_ms":22100,"start_ms":19000,"key_words":["forgot","choice"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":5,"id":"50fb934c-a83b-4009-bdf6-2807a9830f81","sub":null,"part":1,"text":"I let you push me past the breaking point","traps":[{"kind":"linking","note":"t gặp you biến thành âm \"ch\".","real":"/ˈle tʃə/ (nghe như \"LÉ-chơ\")","text":"let you","skill":"yod-coalescence"},{"kind":"linking","note":"t cuối của past mất khi đứng trước the.","real":"/pæs ðə/ (nghe như \"PAS-đơ\")","text":"past the","skill":"t-d-dropping"}],"end_ms":25210,"start_ms":22100,"key_words":["push"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":6,"id":"630de188-2428-41c6-80e2-6b07b0286296","sub":null,"part":1,"text":"I stood for nothing, so I fell for everything","traps":[{"kind":"imagine","note":"Âm \"ơ\" giữa every mất, chỉ còn ba nhịp.","real":"/ˈevriθɪŋ/ (nghe như \"EV-ri-thing\")","text":"everything","skill":"syllable-deletion"}],"end_ms":30760,"start_ms":25210,"key_words":["nothing","everything"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":7,"id":"4e1c7ee7-5320-4588-8d23-319197cce46c","sub":null,"part":1,"text":"You held me down, but I got up","traps":[{"kind":"linking","note":"d của held mất trước me, dễ nghe thành \"hell me\".","real":"/ˈhel mi/ (nghe như \"HEL-mi\")","text":"held me","skill":"t-d-dropping"},{"kind":"linking","note":"t giữa got và up đọc nhẹ như \"đ\".","real":"/ɡɑː ˈɾʌp/ (nghe như \"ga-ĐẮP\")","text":"got up","skill":"flap-t"}],"end_ms":33770,"start_ms":30760,"key_words":["down","up"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":8,"id":"c02ec9e0-3516-4f53-bfcb-a1bfc4e930f0","sub":null,"part":1,"text":"Already brushing off the dust","traps":[{"kind":"linking","note":"Âm cuối của brushing dính sang off.","real":"/ˈbrʌʃɪ ŋɔːf/ (nghe như \"BRẮ-shi-ngóf\")","text":"brushing off","skill":"linking-words"}],"end_ms":36900,"start_ms":34880,"key_words":["dust"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":9,"id":"e0e74bd0-383a-48a0-9a98-0feca7a5895b","sub":null,"part":1,"text":"You hear my voice, you hear that sound","traps":[],"end_ms":40060,"start_ms":36900,"key_words":["voice"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":10,"id":"eeb8013a-36bf-474d-8149-2de963d668fa","sub":null,"part":1,"text":"Like thunder gonna shake the ground","traps":[{"kind":"linking","note":"going to rút lại thành gonna, chỉ còn hai nhịp.","real":"/ˈɡənə/ (nghe như \"GÀ-nơ\")","text":"gonna","skill":"informal-reductions"}],"end_ms":43140,"start_ms":40460,"key_words":["thunder"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":11,"id":"97e47cb3-0316-493e-97c3-b2f11b9e2282","sub":null,"part":1,"text":"Get ready 'cause I've had enough","traps":[{"kind":"linking","note":"d của had dính vào enough, đọc nhẹ như \"đ\".","real":"/hæ ɾɪˈnʌf/ (nghe như \"he-đi-NẮF\")","text":"had enough","skill":"linking-words"}],"end_ms":49110,"start_ms":46250,"key_words":["enough"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":12,"id":"cf7ddad1-c5cc-4aa0-a037-207dff2fe0d3","sub":null,"part":1,"text":"I see it all, I see it now","traps":[{"kind":"linking","note":"t của it chạy sang all, đọc nhẹ như \"đ\".","real":"/ɪ ˈɾɔːl/ (nghe như \"i-ĐOL\")","text":"it all","skill":"flap-t"}],"end_ms":52590,"start_ms":49110,"key_words":["see"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":13,"id":"5596da9d-a019-4c43-8774-130da4dc1af1","sub":null,"part":1,"text":"I got the eye of the lion, a fighter, dancing through the fire","traps":[{"kind":"linking","note":"Giữa eye và of chen thêm một âm \"y\".","real":"/ˈaɪ jəv/ (nghe như \"AI-yơv\")","text":"eye of","skill":"linking-words"}],"end_ms":60890,"start_ms":53070,"key_words":["fighter"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":14,"id":"ffe538b8-fd4a-43f4-98f2-60bddfb1f87d","sub":null,"part":1,"text":"'Cause I am a champion and you're gonna hear me roar","traps":[{"kind":"linking","note":"and với you're dính nhau, đọc lướt rất nhẹ.","real":"/ən dʒər/ (nghe như \"ơn-giơ\")","text":"and you're","skill":"yod-coalescence"}],"end_ms":68720,"start_ms":60890,"key_words":["champion","roar"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"n":15,"id":"b331a15a-9b09-49d8-8c9f-9c76b6aab250","sub":null,"part":1,"text":"Louder, louder than a lion","traps":[{"kind":"linking","note":"than đọc yếu, n nối sang a.","real":"/ðə nə/ (nghe như \"đơ-nơ\")","text":"than a","skill":"weak-forms"}],"end_ms":73190,"start_ms":68720,"key_words":["louder"],"lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"}]$row$::jsonb) on conflict do nothing;
  insert into il_translations ("key", "lang", "text", "lesson_id") select "key", "lang", "text", "lesson_id" from jsonb_populate_recordset(null::il_translations, $row$[{"key":"title","lang":"en-US","text":"Where does the roar in Katy Perry's Roar come from?","lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"key":"intro","lang":"en-US","text":"A slowed version of Roar by Katy Perry, so every word is easier to catch. See how many places you can hear where one word runs into the next.","lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"},{"key":"explore","lang":"en-US","text":"## A song about speaking up\r\nRoar starts with someone used to putting up with things. Afraid of causing trouble, they nod along to whatever others say, until they forget they have a choice.\r\n## Enough is enough\r\nPushed too far, they fall, get back up, brush off the dust and use their voice. The song compares that voice to thunder shaking the ground.\r\n## Eye of the tiger, voice of a lion\r\n- \"Eye of the tiger\" is an American way to talk about a look of fierce determination, made famous by a song tied to the boxing film Rocky.\r\n- The roar is a statement: now everyone is going to hear me.\r\n## Later in the video\r\nKaty mentions a butterfly and a bee, a nod to a famous line by the boxer Muhammad Ali, and tells how she went from nothing to being her own hero.","lesson_id":"aae8d08c-786d-4f39-9ebf-7d37993a2f5b"}]$row$::jsonb) on conflict do nothing;
end $do$;
commit;
